import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IdiscussionBoardModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardModerators";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

/**
 * Test successful revocation of a moderator assignment (demotion/auditability).
 *
 * This test validates the business workflow for moderator demotion by setting
 * the 'revoked_at' field on an existing moderator assignment record. It ensures
 * that administrators can create a member, assign moderator privileges, and then
 * properly revoke (demote) that moderator role. Upon revocation, the API should
 * correctly set the 'revoked_at' timestamp for audit tracking.
 *
 * Steps:
 * 1. Register a member (POST /discussionBoard/actors/members)
 * 2. Assign member as moderator (POST /discussionBoard/actors/moderators)
 * 3. Revoke the moderator assignment (PUT /discussionBoard/actors/moderators/{id}, setting revoked_at)
 * 4. Assert moderator assignment is updated: revoked_at set, all other fields consistent
 */
export async function test_api_discussionBoard_test_update_moderator_assignment_with_valid_revocation(
  connection: api.IConnection
) {
  // 1. Register a new discussion board member
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      is_active: true,
      profile_image_url: null,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(member);

  // 2. Assign the member as moderator
  const moderatorAssignment = await api.functional.discussionBoard.actors.moderators.post(connection, {
    body: {
      member_id: member.id,
      assigned_at: new Date().toISOString(),
    } satisfies IdiscussionBoardModerators.ICreate
  });
  typia.assert(moderatorAssignment);

  // 3. Revoke the moderator assignment
  const now = new Date().toISOString();
  const result = await api.functional.discussionBoard.actors.moderators.putById(connection, {
    id: moderatorAssignment.id,
    body: {
      revoked_at: now,
    } satisfies IDiscussionBoardModerator.IUpdate
  });
  typia.assert(result);

  // 4. Assert moderator assignment fields
  TestValidator.equals("assignment id unchanged")(result.id)(moderatorAssignment.id);
  TestValidator.equals("revoked_at updated")(result.revoked_at)(now);
  TestValidator.equals("member id unchanged")(result.member_id)(moderatorAssignment.member_id);
  TestValidator.equals("assigned_at unchanged")(result.assigned_at)(moderatorAssignment.assigned_at);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IdiscussionBoardModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardModerators";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

/**
 * Verify moderator update endpoint rejects invalid updates via business logic rules.
 *
 * This test ensures that attempts to update moderator assignments that would violate business constraints (e.g., revoking before assignment, setting a clearly invalid assigned_at value) are rejected by the system. Strict schema violations (extra fields, wrong types) cannot be tested directly due to TypeScript type safety and test suite constraints.
 *
 * Steps:
 * 1. Register a member
 * 2. Assign moderator
 * 3. Attempt to set revoked_at to a time before assigned_at (should fail)
 * 4. Attempt to set assigned_at to null (type-legal, but possibly business invalid)
 */
export async function test_api_discussionBoard_actors_moderators_test_update_moderator_assignment_with_invalid_fields(
  connection: api.IConnection,
) {
  // Step 1. Register member
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(32),
      display_name: RandomGenerator.name(),
      is_active: true,
    },
  });
  typia.assert(member);

  // Step 2. Assign moderator
  const assignedAt = new Date();
  const moderator = await api.functional.discussionBoard.actors.moderators.post(connection, {
    body: {
      member_id: member.id,
      assigned_at: assignedAt.toISOString(),
    },
  });
  typia.assert(moderator);

  // Step 3. Try to revoke before assignment date (logical error)
  const revokedBeforeAssigned = new Date(assignedAt.getTime() - 86400000).toISOString();
  await TestValidator.error("revoked_at before assigned_at should error")(() =>
    api.functional.discussionBoard.actors.moderators.putById(connection, {
      id: moderator.id,
      body: {
        revoked_at: revokedBeforeAssigned,
        assigned_at: assignedAt.toISOString(),
      },
    }),
  );

  // Step 4. Try assigning null assigned_at (could be forbidden by business validation, allowed by type)
  await TestValidator.error("assigned_at null may be invalid")(() =>
    api.functional.discussionBoard.actors.moderators.putById(connection, {
      id: moderator.id,
      body: {
        assigned_at: null,
      },
    }),
  );
}

