import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IdiscussionBoardModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardModerators";

/**
 * Validate hard deletion of a moderator assignment in discussion_board_moderators.
 *
 * This test ensures end-to-end that when a moderator assignment is deleted using the DELETE endpoint, the record is fully removed (hard delete)—not just soft-deleted, but truly deleted from the system.
 *
 * Workflow Steps:
 * 1. Create a new discussion board member.
 * 2. Assign this member as a moderator, receiving a moderator assignment id.
 * 3. Delete the moderator assignment with the assignment id.
 *
 * Business Context:
 * - Only administrator users should be able to escalate or revoke moderator assignments, but this test focuses on the technical contract.
 * - There is no soft delete mechanism in the moderator assignments table: deletion is permanent.
 *
 * Validations:
 * - Successful deletion returns no content and no error (DELETE endpoint contract).
 */
export async function test_api_discussionBoard_test_delete_moderator_assignment_success(
  connection: api.IConnection,
) {
  // Step 1: Create a discussion board member
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(20),
      display_name: RandomGenerator.name(),
      profile_image_url: null,
      is_active: true,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(member);

  // Step 2: Assign the member as moderator
  const now = new Date().toISOString();
  const moderatorAssignment = await api.functional.discussionBoard.actors.moderators.post(connection, {
    body: {
      member_id: member.id,
      assigned_at: now,
    } satisfies IdiscussionBoardModerators.ICreate,
  });
  typia.assert(moderatorAssignment);

  // Step 3: Delete the moderator assignment
  await api.functional.discussionBoard.actors.moderators.eraseById(connection, {
    id: moderatorAssignment.id,
  });
}

