/**
 * Validate listing administrator assignments with non-matching (bogus) filters returns empty results.
 *
 * This test verifies that when the administrator assignment listing API is supplied with filters or criteria that do not match any records (e.g., fake UUID, impossible date), the API returns an empty "data" array but a valid "pagination" object, confirming correct handling of empty search results and compliance with paging contract.
 *
 * Step-by-step:
 * 1. Compose bogus filters for member_id (random UUID not in use) and/or date fields outside the range of any possible assignment.
 * 2. Call the patch API to list administrator assignments using these filters.
 * 3. Check the response for an empty data array ([]), but a present and valid pagination object.
 * 4. Confirm type safety and correctness throughout.
 */
export async function test_api_discussionBoard_test_list_admin_assignments_empty_result(
  connection: api.IConnection,
) {
  // Step 1: Create bogus search filters (random UUID, implausible date)
  const bogus_member_id = typia.random<string & tags.Format<"uuid">>();
  const bogus_assigned_at = "1900-01-01T00:00:00.000Z"; // Well outside any realistic assignment
  const requestBody: IDiscussionBoardAdministrator.IRequest = {
    member_id: bogus_member_id,
    assigned_at: bogus_assigned_at,
    page: 1,
    limit: 10,
  };

  // Step 2: Call the API to list admin assignments with non-matching filters
  const output = await api.functional.discussionBoard.actors.administrators.patch(
    connection,
    { body: requestBody },
  );
  typia.assert(output);

  // Step 3: Validate empty data result and correct pagination
  TestValidator.equals("should be empty data array")(output.data)([]);
  TestValidator.predicate("valid pagination metadata")(!!output.pagination);
  TestValidator.equals("current page is 1")(output.pagination.current)(1);
  TestValidator.equals("limit is 10")(output.pagination.limit)(10);
  TestValidator.equals("total records should be 0")(output.pagination.records)(0);
  TestValidator.equals("total pages should be 0")(output.pagination.pages)(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
