/**
 * Validate that an administrator assignment can be retrieved correctly by its id.
 *
 * This test executes the full logical workflow for admin assignment retrieval:
 * 1. Create a new discussion board member with valid sign-up fields.
 * 2. Assign administrator privileges to that member and capture the resulting assignment record.
 * 3. Retrieve the administrator assignment by its id using the dedicated endpoint.
 * 4. Verify that the fetched assignment matches the original assignment created (all fields).
 *
 * This assures not only correct retrieval but confirms integrity of the role escalation and record linkage.
 */
export async function test_api_discussionBoard_actors_administrators_test_get_admin_assignment_by_valid_id(
  connection: api.IConnection,
) {
  // 1. Create a new discussion board member
  const memberInput: IdiscussionBoardMembers.ICreate = {
    username: RandomGenerator.alphabets(10),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(24),
    display_name: RandomGenerator.name(),
    profile_image_url: null,
    is_active: true,
  };
  const member = await api.functional.discussionBoard.actors.members.post(connection, { body: memberInput });
  typia.assert(member);

  // 2. Assign administrator role to the member
  const adminInput: IDiscussionBoardAdministrator.ICreate = {
    member_id: member.id,
    assigned_at: new Date().toISOString() as string & tags.Format<"date-time">,
  };
  const createdAdmin = await api.functional.discussionBoard.actors.administrators.post(connection, { body: adminInput });
  typia.assert(createdAdmin);

