import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardSearchHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSearchHistory";

/**
 * Validates member-driven deletion of a search history record by UUID, ensuring proper hard deletion.
 *
 * This test simulates a real member workflow:
 * 1. Register a new discussion board member (ensures fresh, unique actor).
 * 2. Perform a search as that member to create a search history record.
 * 3. Confirm the search history record exists by fetching it by UUID.
 * 4. Delete the search history record (member deletes their own history).
 * 5. Attempt to re-fetch the deleted record and assert a not-found error is raised.
 *
 * This covers normal member workflow, verifies authorization on deletion, and validates the hard deletion (record truly gone, not soft-deleted).
 */
export async function test_api_discussionBoard_test_delete_search_history_with_valid_id_owned_by_user(
  connection: api.IConnection,
) {
  // 1. Register a member
  const memberInput: IdiscussionBoardMembers.ICreate = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(16),
    display_name: RandomGenerator.name(),
    profile_image_url: null,
    is_active: true,
  };
  const member = await api.functional.discussionBoard.actors.members.post(connection, { body: memberInput });
  typia.assert(member);

  // 2. Member performs a search -> this creates a history entry
  const searchInput: IDiscussionBoardSearchHistory.ICreate = {
    actor_id: member.id,
    keyword: RandomGenerator.alphabets(12),
    filters: JSON.stringify({ category: "general", sort: "desc" }),
    search_context: "thread_list",
    created_at: new Date().toISOString() as string & tags.Format<"date-time">,
  };
  const searchHistory = await api.functional.discussionBoard.search.searchHistories.post(connection, { body: searchInput });
  typia.assert(searchHistory);

  // 3. Confirm record exists before delete
  const beforeDelete = await api.functional.discussionBoard.search.searchHistories.getById(connection, { id: searchHistory.id });
  typia.assert(beforeDelete);
  TestValidator.equals("search history id before deletion")(beforeDelete.id)(searchHistory.id);

  // 4. Delete the search history record
  await api.functional.discussionBoard.search.searchHistories.eraseById(connection, { id: searchHistory.id });

  // 5. Attempt to fetch record again and expect not-found error
  await TestValidator.error("search history should not be found after delete")(async () => {
    await api.functional.discussionBoard.search.searchHistories.getById(connection, { id: searchHistory.id });
  });
}

