import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardSearchHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSearchHistory";

/**
 * Tests that a member cannot delete another member's search history record.
 *
 * This test covers a critical permission-checking scenario in which one actor (member) is not allowed to delete search histories owned by someone else. The workflow is as follows:
 * 1. Register Member 1 ("owner") and Member 2 ("non-owner") as separate accounts.
 * 2. Member 1 signs up and creates a search history record.
 * 3. Member 2 signs up and attempts to delete the search history record owned by Member 1, using its ID.
 * 4. The DELETE API call (as Member 2) must fail, asserting that a permission error is thrown and the record remains untouched.
 * 5. Finally, fetch the search history entry by ID as Member 1 to confirm its existence.
 *
 * Key Assertions:
 * - The API must reject the deletion attempt with a permissions error (not found, forbidden, etc.) when a non-owner tries to delete the record.
 * - The record remains intact after the failed delete attempt.
 */
export async function test_api_discussionBoard_test_delete_search_history_by_non_owner_permission_denied(
  connection: api.IConnection,
) {
  // 1. Register two members: owner and non-owner
  const member1Data = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(12),
    display_name: RandomGenerator.name(),
    is_active: true,
    profile_image_url: null,
  } satisfies IdiscussionBoardMembers.ICreate;
  const member2Data = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(12),
    display_name: RandomGenerator.name(),
    is_active: true,
    profile_image_url: null,
  } satisfies IdiscussionBoardMembers.ICreate;

  // Register Member 1 (owner)
  const member1 = await api.functional.discussionBoard.actors.members.post(connection, { body: member1Data });
  typia.assert(member1);

  // Register Member 2 (non-owner)
  const member2 = await api.functional.discussionBoard.actors.members.post(connection, { body: member2Data });
  typia.assert(member2);

  // 2. Member 1 creates a search history record
  const historyInput = {
    actor_id: member1.id,
    keyword: RandomGenerator.paragraph()(2),
    filters: null,
    search_context: "thread_list",
    created_at: new Date().toISOString(),
  } satisfies IDiscussionBoardSearchHistory.ICreate;
  const createdHistory = await api.functional.discussionBoard.search.searchHistories.post(connection, { body: historyInput });
  typia.assert(createdHistory);

  // 3. Member 2 attempts to delete Member 1's search history (should fail)
  await TestValidator.error("non-owner cannot delete other's search history")(() =>
    api.functional.discussionBoard.search.searchHistories.eraseById(connection, { id: createdHistory.id })
  );

  // 4. Owner fetches the history record to verify it still exists
  const reloaded = await api.functional.discussionBoard.search.searchHistories.getById(connection, { id: createdHistory.id });
  typia.assert(reloaded);
  TestValidator.equals("actor_id not changed")(reloaded.actor_id)(member1.id);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdministrator";
import type { IDiscussionBoardSearchHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSearchHistory";

/**
 * Verify that an administrator can delete any user's search history record.
 *
 * This test follows a full business workflow:
 * 1. Register a standard member account.
 * 2. Register a second member account (intended for admin escalation).
 * 3. Escalate the second member to administrator status.
 * 4. Log in as the first member, and create a search history record.
 * 5. (Optional: fetch the search history record as member to verify existence.)
 * 6. Log in as the admin user.
 * 7. As admin, delete the member's search history record by ID.
 * 8. Assert DELETE succeeded (no error is thrown).
 * 9. Attempt to fetch the deleted record—expect a not-found error, confirming deletion.
 *
 * This ensures that administrators have override capabilities to delete any user's search history in accordance with admin policies, and that deletions are effective and irreversible.
 */
export async function test_api_discussionBoard_test_admin_can_delete_any_search_history_record(
  connection: api.IConnection,
) {
  // 1. Register the first member (regular user)
  const member1Email = typia.random<string & tags.Format<"email">>();
  const member1Username = RandomGenerator.alphabets(8);
  const member1: IdiscussionBoardMembers = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: member1Username,
      email: member1Email,
      hashed_password: RandomGenerator.alphaNumeric(15),
      display_name: RandomGenerator.name(),
      is_active: true,
      profile_image_url: null,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(member1);

  // 2. Register the second member (to escalate to admin)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminUsername = RandomGenerator.alphabets(8);
  const adminMember: IdiscussionBoardMembers = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: adminUsername,
      email: adminEmail,
      hashed_password: RandomGenerator.alphaNumeric(15),
      display_name: RandomGenerator.name(),
      is_active: true,
      profile_image_url: null,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(adminMember);

  // 3. Escalate the second member to administrator status
  const adminPrivilege = await api.functional.discussionBoard.actors.administrators.post(connection, {
    body: {
      member_id: adminMember.id,
      assigned_at: new Date().toISOString(),
    } satisfies IDiscussionBoardAdministrator.ICreate,
  });
  typia.assert(adminPrivilege);

  // 4. Create a search history entry as the first member
  // (Assume session switching if needed, otherwise test is run as superuser)
  const searchHistory: IDiscussionBoardSearchHistory = await api.functional.discussionBoard.search.searchHistories.post(connection, {
    body: {
      actor_id: member1.id,
      keyword: RandomGenerator.alphaNumeric(12),
      filters: null,
      search_context: "thread_list",
      created_at: new Date().toISOString(),
    } satisfies IDiscussionBoardSearchHistory.ICreate,
  });
  typia.assert(searchHistory);

  // 5. Fetch the search history record by id to verify existence
  const fetched: IDiscussionBoardSearchHistory = await api.functional.discussionBoard.search.searchHistories.getById(connection, {
    id: searchHistory.id,
  });
  typia.assert(fetched);
  TestValidator.equals("Search history id equality")(fetched.id)(searchHistory.id);
  TestValidator.equals("Actor id equality")(fetched.actor_id)(member1.id);

  // 6. (If session switching required: Switch to admin login, else assume admin powers)

  // 7. As admin, delete the member's search history record by ID
  await api.functional.discussionBoard.search.searchHistories.eraseById(connection, {
    id: searchHistory.id,
  });

  // 8. Assert API DELETE success (no error throws)
  // (Implicitly done above)

  // 9. Attempt to fetch deleted record; expect not-found error
  await TestValidator.error("search history not found after deletion")(() =>
    api.functional.discussionBoard.search.searchHistories.getById(connection, {
      id: searchHistory.id,
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IdiscussionBoardModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardModerators";
import type { IDiscussionBoardModerationLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerationLog";
import type { IModerationModerationLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerationModerationLog";

/**
 * Test successful update of action and action_reason fields for a moderation log by an authorized moderator
 *
 * This test simulates the real-world workflow of updating a moderation event log's action and reason. It covers:
 * 1. Creating a new forum member
 * 2. Assigning moderator privileges (escalation)
 * 3. Creating a moderation log entry
 * 4. Performing an update to change action and action_reason fields
 * 5. Validating that changes applied correctly,
 *    - all other immutable fields are unchanged
 *    - business logic is fully respected
 */
export async function test_api_discussionBoard_moderation_moderationLogs_test_update_moderation_log_action_and_reason_success(
  connection: api.IConnection,
) {
  // 1. Create a new member
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphabets(16),
      display_name: RandomGenerator.name(),
      is_active: true,
      profile_image_url: null,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(member);

  // 2. Escalate the member to moderator status
  const now = new Date().toISOString();
  const moderator = await api.functional.discussionBoard.actors.moderators.post(connection, {
    body: {
      member_id: member.id,
      assigned_at: now,
    } satisfies IdiscussionBoardModerators.ICreate,
  });
  typia.assert(moderator);

  // 3. Create a moderation log entry
  const moderationLog = await api.functional.discussionBoard.moderation.moderationLogs.post(connection, {
    body: {
      moderator_id: moderator.id,
      action: "hide",
      action_reason: "Original post violated guidelines.",
      thread_id: null,
      post_id: null,
      comment_id: null,
    } satisfies IDiscussionBoardModerationLog.ICreate,
  });
  typia.assert(moderationLog);

  // 4. Update action and action_reason fields of the moderation log
  const newAction = "delete";
  const newReason = "Post contained prohibited content.";
  const updatedLog = await api.functional.discussionBoard.moderation.moderationLogs.putById(connection, {
    id: moderationLog.id,
    body: {
      action: newAction,
      action_reason: newReason,
    } satisfies IModerationModerationLog.IUpdate,
  });
  typia.assert(updatedLog);

  // 5. Validate only the intended changes occurred
  TestValidator.equals("updated action")(updatedLog.action)(newAction);
  TestValidator.equals("updated action_reason")(updatedLog.action_reason)(newReason);
  TestValidator.equals("moderator_id unchanged")(updatedLog.moderator_id)(moderationLog.moderator_id);
  TestValidator.equals("thread_id unchanged")(updatedLog.thread_id)(moderationLog.thread_id);
  TestValidator.equals("post_id unchanged")(updatedLog.post_id)(moderationLog.post_id);
  TestValidator.equals("comment_id unchanged")(updatedLog.comment_id)(moderationLog.comment_id);
  TestValidator.equals("created_at unchanged")(updatedLog.created_at)(moderationLog.created_at);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IModerationModerationLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerationModerationLog";

/**
 * Validates that attempting to update a non-existent moderation log triggers the correct not-found error.
 *
 * Business context:
 * Moderation logs in the discussion board system are immutable audit records. Modifying an entry requires referencing an existing log's unique UUID. If an update attempt is made on a UUID that does not exist in the database, the API should reject it—typically with a 404 Not Found error. This test ensures that the update endpoint upholds this business rule, guards against improper creation-on-update semantics, and enforces reliable audit trail immutability.
 *
 * Test Workflow:
 * 1. Generate a random UUID that does not map to any real moderation log.
 * 2. Formulate a valid update payload with legitimate fields.
 * 3. Attempt the update using the fake/invalid UUID.
 * 4. Assert that the operation fails (any error thrown is sufficient—do not check error type or message specifics).
 *
 * This test guarantees that no accidental creation or update occurs on invalid IDs and that proper not-found handling is enforced.
 */
export async function test_api_discussionBoard_moderation_moderationLogs_putById_test_update_moderation_log_invalid_id_not_found(
  connection: api.IConnection,
) {
  // 1. Generate a random UUID not corresponding to any moderation log record
  const invalidId = typia.random<string & tags.Format<"uuid">>();

  // 2. Construct a minimal valid update payload
  const updatePayload = {
    action: "edit",
    action_reason: "Attempt to update non-existent log (negative test)",
  } satisfies IModerationModerationLog.IUpdate;

  // 3. Attempt to update the log; assert that an error is thrown
  await TestValidator.error("Should throw not-found error on invalid moderation log ID")(
    () =>
      api.functional.discussionBoard.moderation.moderationLogs.putById(
        connection,
        {
          id: invalidId,
          body: updatePayload,
        },
      ),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
