 * 1. Create a discussion board member (target of warning).
 * 2. Assign a moderator role to the newly created member.
 * 3. Prepare warning request data (with all duplicate-prone fields identical: member, moderator, type, message, created_at).
 * 4. Create the first warning.
 * 5. Attempt to create a second warning with identical data.
 * 6. If duplicate allowed, verify returned warnings have different IDs but otherwise identical details.
 * 7. If system enforces idempotency or uniqueness, verify duplicate attempt fails cleanly with proper error handling using TestValidator.
 */
export async function test_api_discussionBoard_moderation_warnings_test_create_warning_duplicate_idempotency_or_uniqueness(
  connection: api.IConnection,
) {
  // 1. Create a discussion board member (target of warning)
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(20),
      display_name: RandomGenerator.name(),
      is_active: true,
      profile_image_url: null,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(member);

  // 2. Assign moderator role to this member
  const moderator = await api.functional.discussionBoard.actors.moderators.post(connection, {
    body: {
      member_id: member.id,
      assigned_at: new Date().toISOString(),
    } satisfies IdiscussionBoardModerators.ICreate,
  });
  typia.assert(moderator);

  // 3. Prepare warning data (fields identical for both attempts)
  const warningInput = {
    member_id: member.id,
    moderator_id: moderator.id,
    warning_type: "spam",
    message: "Repeated spam content in forum thread.",
    created_at: new Date().toISOString(),
    expires_at: null,
  } satisfies IModerationWarning.ICreate;

  // 4. Create first warning
  const warning1 = await api.functional.discussionBoard.moderation.warnings.post(connection, {
    body: warningInput,
  });
  typia.assert(warning1);

  // 5. Attempt to create duplicate warning (identical input)
  let warning2: IModerationWarning | null = null;
  let duplicateRejected = false;
  try {
    warning2 = await api.functional.discussionBoard.moderation.warnings.post(connection, { body: warningInput });
    typia.assert(warning2);
  } catch {
    duplicateRejected = true;
  }

  // 6. Branch: allowed duplicate or uniqueness enforced
  if (!duplicateRejected) {
    TestValidator.notEquals("warning IDs must differ")(warning1.id)(warning2!.id);
    TestValidator.equals("member_id identical")(warning1.member_id)(warning2!.member_id);
    TestValidator.equals("moderator_id identical")(warning1.moderator_id)(warning2!.moderator_id);
    TestValidator.equals("warning_type identical")(warning1.warning_type)(warning2!.warning_type);
    TestValidator.equals("message identical")(warning1.message)(warning2!.message);
  } else {
    TestValidator.predicate("duplicate warning correctly blocked")(duplicateRejected);
  }
}

