  // 4. Multi-criteria search: by code and name together
  const namePick = pick.name;
  const multiResp = await api.functional.discussionBoard.votes.voteTypes.patch(
    connection,
    { body: { code: pick.code, name: namePick } satisfies discussion_board_vote_types.IRequest }
