 * 2. Promote the member to administrator (create assignment, capture id).
 * 3. Prepare a valid administrator update payload (e.g., assign new assigned_at).
 * 4. Add an extra non-schema property to the payload (e.g., audit_trace: "test-metadata").
 * 5. Attempt the update using administrators.putById. Expect a validation error and no update performed.
 * 6. Perform a valid update (without extra property) as positive control to show success and clean up state.
 */
export async function test_api_discussionBoard_actors_administrators_test_update_administrator_schema_violation_field_rejected(
  connection: api.IConnection,
) {
  // Step 1: Create a new member
  const memberInput = {
    username: RandomGenerator.alphabets(10),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphabets(24),
