 *
 * 두 개의 고유 설정을 생성한 후,
 * 두 번째 설정의 key를 첫 번째와 동일하게 변경하려 하면 반드시 고유 제약 조건 에러가 발생해야 한다.
 *
 * [테스트 절차]
 * 1. 첫 번째 구성(keyA, valueA) 생성 및 저장 정상 확인
 * 2. 두 번째 구성(keyB, valueB) 생성 및 저장 정상 확인
 * 3. 두 번째 구성의 key를 keyA로 변경하려 시도 → 중복 에러 발생 필수
 */
export async function test_api_discussionBoard_test_update_configuration_with_duplicate_key_returns_unique_constraint_error(
  connection: api.IConnection,
) {
  // 1. 첫 번째 구성 생성 및 저장
  const keyA = `key-${RandomGenerator.alphabets(8)}`;
  const valueA = `value-${RandomGenerator.alphabets(8)}`;
  const configA = await api.functional.discussionBoard.systematic.configurations.post(connection, {
    body: {
      key: keyA,
      value: valueA,
      description: "설정 1 고유키",
    },
  });
  typia.assert(configA);
  TestValidator.equals("keyA 저장 확인")(configA.key)(keyA);

  // 2. 두 번째 구성 생성 및 저장
  const keyB = `key-${RandomGenerator.alphabets(8)}`;
  const valueB = `value-${RandomGenerator.alphabets(8)}`;
  const configB = await api.functional.discussionBoard.systematic.configurations.post(connection, {
    body: {
      key: keyB,
      value: valueB,
      description: "설정 2 고유키",
    },
  });
  typia.assert(configB);
  TestValidator.equals("keyB 저장 확인")(configB.key)(keyB);

  // 3. 두 번째 구성의 key를 중복값(keyA)으로 변경 시도 -> 반드시 에러 발생해야 함
  await TestValidator.error("중복된 key로 업데이트 시 에러 발생하는지 검증")(
    async () => {
      await api.functional.discussionBoard.systematic.configurations.putById(connection, {
        id: configB.id,
        body: {
          key: keyA,
        },
      });
    }
  );
}

