      email: email2,
      hashed_password: RandomGenerator.alphaNumeric(32),
      display_name: display_name2,
      is_active: true,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(output2);
  TestValidator.equals('profile_image_url null')(output2.profile_image_url)(null);

  // Step 3a: Attempt duplicate username
  const new_email = typia.random<string & tags.Format<'email'>>();
  await TestValidator.error('duplicate username should fail')(() =>
    api.functional.discussionBoard.actors.members.post(connection, {
      body: {
        username,
        email: new_email,
        hashed_password: RandomGenerator.alphaNumeric(32),
        display_name: RandomGenerator.name(),
        is_active: true,
      } satisfies IdiscussionBoardMembers.ICreate,
    }),
  );

  // Step 3b: Attempt duplicate email
  const new_username = RandomGenerator.alphaNumeric(12);
  await TestValidator.error('duplicate email should fail')(() =>
    api.functional.discussionBoard.actors.members.post(connection, {
      body: {
        username: new_username,
        email,
        hashed_password: RandomGenerator.alphaNumeric(32),
        display_name: RandomGenerator.name(),
        is_active: true,
      } satisfies IdiscussionBoardMembers.ICreate,
    }),
  );

  // Step 3c: Invalid email format
  await TestValidator.error('invalid email format should fail')(() =>
    api.functional.discussionBoard.actors.members.post(connection, {
      body: {
        username: RandomGenerator.alphaNumeric(12),
        email: 'notanemail',
        hashed_password: RandomGenerator.alphaNumeric(32),
        display_name: RandomGenerator.name(),
        is_active: true,
      } as any, // Forced fail for email: out-of-schema but testable at runtime
    }),
  );

  // Step 3d: Missing required fields - not possible if SDK does not accept, so skipped if TS error would occur
}

