import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardChannel";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageDiscussionBoardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionBoardChannel";

/**
 * 키워드(부분일치) 및 페이지네이션이 결합된 토론 채널 목록 조회 검증.
 *
 * 관리자 뷰, 어드민에서 사용할 수 있는 채널 관리 검색을 전제로 한다.
 *
 * [절차]
 * 1. 다양한 code, name, description 조합으로 채널 여러 개 등록(적어도 6개 이상)
 * 2. code의 일부(keyword)를 검색어로 하여 부분일치+페이지네이션 1page 검색 및 응답검증
 *    - code 일부와 일치하는 데이터만 반환되는지, 한페이지 크기만큼만 오는지
 *    - pagination.current/limit/records 등 메타 일치성 체크
 * 3. name 일부(keyword)를 검색어로 하여 2페이지 검색 및 일치성 응답검증
 *    - name 일부와 일치하는 데이터만 반환, 2page/2개씩 등 검증
 * 4. 일치하는 code, name, description이 아예 없는 zero-result 검색에서 empty 확인
 * 5. 각 단계 데이터는 모두 typia.assert, TestValidator로 정밀 검증
 */
export async function test_api_discussionBoard_test_search_channels_with_keyword_and_pagination(
  connection: api.IConnection,
) {
  // 1. 여러 code, name, description 조합으로 6개 채널 생성
  const channels: IDiscussionBoardChannel[] = [];
  for (let i = 0; i < 6; ++i) {
    const code = `eco-keyword-${i}`;
    const name = `TestNameKeywordMatch${i}`;
    const description = i % 2 === 0
      ? `description with keyword${i}`
      : `misc-description-${i}`;
    const created: IDiscussionBoardChannel = await api.functional.discussionBoard.systematic.channels.post(connection, {
      body: { code, name, description } satisfies IDiscussionBoardChannel.ICreate,
    });
    typia.assert(created);
    channels.push(created);
  }

  // 2. 코드 일부로 keyword 검색 + 페이지네이션(page=1, limit=3)
  const codeKeyword = 'eco-keyword-';
  const codeSearch: IPageDiscussionBoardChannel = await api.functional.discussionBoard.systematic.channels.patch(connection, {
    body: {
      code: codeKeyword,
      pagination: { current: 1, limit: 3, records: 0, pages: 0 }, // records/pages: 임의값으로 type 맞춤
    } satisfies IDiscussionBoardChannel.IRequest,
  });
  typia.assert(codeSearch);
  for (const c of codeSearch.data) {
    typia.assert(c);
    TestValidator.predicate('code matched keyword')(c.code.includes(codeKeyword));
  }
  TestValidator.equals('pagination.current')(codeSearch.pagination.current)(1);
  TestValidator.equals('pagination.limit')(codeSearch.pagination.limit)(3);
  TestValidator.equals('pagination.records')(codeSearch.pagination.records)(channels.length);

  // 3. 이름 일부로 keyword 검색 + 2페이지(2개씩) 검색
  const nameKeyword = 'KeywordMatch';
  const nameSearch: IPageDiscussionBoardChannel = await api.functional.discussionBoard.systematic.channels.patch(connection, {
    body: {
      name: nameKeyword,
      pagination: { current: 2, limit: 2, records: 0, pages: 0 },// 임의값
    } satisfies IDiscussionBoardChannel.IRequest,
  });
  typia.assert(nameSearch);
  for (const c of nameSearch.data) {
    typia.assert(c);
    TestValidator.predicate('name matched keyword')(c.name.includes(nameKeyword));
  }
  TestValidator.equals('pagination.current')(nameSearch.pagination.current)(2);
  TestValidator.equals('pagination.limit')(nameSearch.pagination.limit)(2);

  // 4. 일치하는게 없는 케이스(code, name, description 모두 미일치)
  const notFoundSearch: IPageDiscussionBoardChannel = await api.functional.discussionBoard.systematic.channels.patch(connection, {
    body: {
      code: 'ZZZZZZ-404',
      name: 'NoSuchName',
      description: 'NoSuchDesc',
      pagination: { current: 1, limit: 2, records: 0, pages: 0 }, // 임의값
    } satisfies IDiscussionBoardChannel.IRequest,
  });
  typia.assert(notFoundSearch);
  TestValidator.equals('empty result')(notFoundSearch.data.length)(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardChannel";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageDiscussionBoardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionBoardChannel";

/**
 * 검색 시 소프트 삭제(soft-deleted)된 채널도 포함할 수 있는지 검증하는 테스트입니다.
 *
 * 1. 여러 개의 채널을 생성합니다.
 * 2. 하나의 채널을 소프트 삭제(eraseById)합니다.
 * 3. 소프트 삭제된 항목을 포함하여 검색(deleted: true)합니다.
 * 4. 응답 결과에 활성(생성/삭제되지 않은)과 소프트 삭제된 채널이 모두 포함되어 있는지 검증합니다.
 * 5. 삭제된 채널의 deleted_at 필드가 실제로 ISO8601 timestamp로 들어가 있는지 확인합니다.
 * 6. 활성화 채널의 deleted_at은 null 또는 undefined인지 확인합니다.
 */
export async function test_api_discussionBoard_systematic_channels_test_search_channels_include_soft_deleted(
  connection: api.IConnection,
) {
  // 1. 여러 개의 채널을 생성합니다.
  const createdChannels: IDiscussionBoardChannel[] = [];
  // 충분한 판별을 위해 최소 3개 생성
  for (let i = 0; i < 3; ++i) {
    const input: IDiscussionBoardChannel.ICreate = {
      code: `ch-${RandomGenerator.alphaNumeric(8)}-${i}`,
      name: `Discussion Channel ${RandomGenerator.alphaNumeric(4)}`,
      description: `테스트용 채널 #${i}`,
    };
    const channel: IDiscussionBoardChannel = await api.functional.discussionBoard.systematic.channels.post(connection, {
      body: input,
    });
    typia.assert(channel);
    createdChannels.push(channel);
  }
  // 2. 하나의 채널을 소프트 삭제합니다.
  const toDelete = createdChannels[1];
  const deleted: IDiscussionBoardChannel = await api.functional.discussionBoard.systematic.channels.eraseById(connection, {
    id: toDelete.id,
  });
  typia.assert(deleted);
  TestValidator.predicate("deleted_at은 소프트 삭제 후 ISO8601 timestamp 값이어야 함")(typeof deleted.deleted_at === "string" && deleted.deleted_at.length > 0);

  // 3. 소프트 삭제 포함해서 검색합니다.
  const searched = await api.functional.discussionBoard.systematic.channels.patch(connection, {
    body: {
      deleted: true,
      pagination: { current: 1, limit: 20, records: 0, pages: 0 },
    },
  });
  typia.assert(searched);

  // 4. 삭제된 채널과 활성 채널 모두 존재하는지 확인
  const foundIds = searched.data.map((x) => x.id);
  for (const c of createdChannels) {
    TestValidator.predicate(`생성된 채널 ${c.id} 검색 결과 포함 여부`)(foundIds.includes(c.id));
  }
  // 5. 삭제된 채널의 deleted_at이 올바르게 셋팅되어 있는지
  const deletedItem = searched.data.find((x) => x.id === toDelete.id);
  TestValidator.predicate("삭제된 채널의 deleted_at은 ISO8601 timestamp이어야 함")(
    !!deletedItem && typeof deletedItem.deleted_at === "string" && deletedItem.deleted_at.length > 0,
  );
  // 6. 살아있는(삭제되지 않은) 채널의 deleted_at은 null 또는 undefined여야 함
  for (const c of createdChannels.filter(x => x.id !== toDelete.id)) {
    const living = searched.data.find((x) => x.id === c.id);
    TestValidator.predicate(`활성 채널 ${c.id}의 deleted_at은 null 또는 undefined여야 함`)(!living?.deleted_at);
  }
}

