  TestValidator.equals("name 일치")(fetched.name)(createInput.name);
  TestValidator.equals("description 일치")(fetched.description)(createInput.description);

  // 4. created/updated_at이 ISO 형식인지 및 값 타입 체크
  TestValidator.predicate("created_at ISO 8601")(!!Date.parse(fetched.created_at));
  TestValidator.predicate("updated_at ISO 8601")(!!Date.parse(fetched.updated_at));

  // 5. deleted_at이 없다면(null 또는 undefined) 정상임
  TestValidator.predicate("새 채널은 삭제상태 아님")(
    fetched.deleted_at === null || typeof fetched.deleted_at === "undefined"
  );
}

