    const fetched = await api.functional.discussionBoard.systematic.channels.getById(connection, {
      id: created.id,
    });
    typia.assert(fetched);
    fetchResult = fetched;
  } catch (err) {
    fetchError = err;
  }

  // 4. Validate policy: returned with deleted_at or error on access
  if (fetchResult !== undefined) {
    TestValidator.predicate("soft-deleted channel fetch yields deleted_at value")(!!fetchResult.deleted_at);
  } else {
    TestValidator.error("fetching soft-deleted channel results in error")(() => {
      if (fetchError === undefined) throw new Error("Expected error, got none");
      throw fetchError;
    });
  }
}

