 *
 * 두 개의 채널을 서로 다른 코드로 차례로 생성한 후,
 * 두 번째 채널의 코드를 첫 번째 채널의 코드로 업데이트 시도했을 때
 * API가 고유 제약(Unique Constraint) 에러를 반환하는지 확인합니다.
 *
 * 1. 첫 번째 채널을 고유 code로 생성
 * 2. 두 번째 채널을 또 다른 고유 code로 생성
 * 3. 두 번째 채널을 첫 번째의 code로 변경 시도 → 실패해야 함
 */
export async function test_api_discussionBoard_systematic_channels_test_update_channel_code_to_duplicate(
  connection: api.IConnection,
) {
  // 1. 첫 번째 채널 생성: 고유 code 사용
  const codeA = `codeA_${RandomGenerator.alphabets(8)}`;
  const channelA = await api.functional.discussionBoard.systematic.channels.post(
    connection,
    {
      body: {
        code: codeA,
        name: `채널A_${RandomGenerator.alphabets(8)}`,
        description: "유니크 테스트용 첫 번째 채널",
      } satisfies IDiscussionBoardChannel.ICreate,
    },
  );
  typia.assert(channelA);
  TestValidator.equals("codeA 채널 코드")(channelA.code)(codeA);

  // 2. 두 번째 채널 생성: 또 다른 고유 code
  const codeB = `codeB_${RandomGenerator.alphabets(8)}`;
  const channelB = await api.functional.discussionBoard.systematic.channels.post(
    connection,
    {
      body: {
        code: codeB,
        name: `채널B_${RandomGenerator.alphabets(8)}`,
        description: "유니크 테스트용 두 번째 채널",
      } satisfies IDiscussionBoardChannel.ICreate,
    },
  );
  typia.assert(channelB);
  TestValidator.equals("codeB 채널 코드")(channelB.code)(codeB);

  // 3. 두 번째 채널의 code를 첫 번째 채널의 code로 변경 시도 → unique 제약 에러를 기대
  await TestValidator.error("채널 코드 중복 업데이트는 실패해야 함")(
