        connection,
        {
          id: channelB.id,
          body: {
            code: codeA,
          } satisfies IDiscussionBoardChannel.IUpdate,
        },
      ),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
