/**
 * Test soft-deleting a discussion board channel by setting deleted_at.
 *
 * This test verifies that the channel "delete" operation correctly marks a channel as deleted by updating the deleted_at field, rather than removing the record.
 *
 * Workflow:
 * 1. Create a new discussion board channel by supplying unique code, name, and optional description.
 * 2. Soft-delete the created channel by calling the eraseById (delete) API with its id.
 * 3. Validate:
 *    - The returned object has the same id, code, name, and description as originally created.
 *    - The deleted_at field is set to a valid date-time string (not null or undefined), proving soft-deletion.
 */
export async function test_api_discussionBoard_systematic_channels_test_soft_delete_channel_by_id(
  connection: api.IConnection,
) {
  // 1. Create a channel with unique code and name (description optional)
  const createdChannel = await api.functional.discussionBoard.systematic.channels.post(
    connection,
    {
      body: {
        code: RandomGenerator.alphaNumeric(8),
        name: RandomGenerator.name(),
        description: Math.random() < 0.5 ? RandomGenerator.paragraph()(1) : undefined,
      } satisfies IDiscussionBoardChannel.ICreate,
    },
  );
  typia.assert(createdChannel);

  // 2. Soft-delete the channel by its id
  const deletedChannel = await api.functional.discussionBoard.systematic.channels.eraseById(
    connection,
    {
      id: createdChannel.id,
    },
  );
  typia.assert(deletedChannel);

  // 3. Confirm that id/code/name/description are preserved, and deleted_at is set to a valid date-time
  TestValidator.equals("id matches")(deletedChannel.id)(createdChannel.id);
  TestValidator.equals("code matches")(deletedChannel.code)(createdChannel.code);
  TestValidator.equals("name matches")(deletedChannel.name)(createdChannel.name);
  TestValidator.equals("description matches")(deletedChannel.description ?? null)(createdChannel.description ?? null);

  // deleted_at should be a non-null ISO8601 string
  TestValidator.predicate("deleted_at is set")(!!deletedChannel.deleted_at);
  if (deletedChannel.deleted_at) typia.assert<string & tags.Format<"date-time">>(deletedChannel.deleted_at);
}

