/**
 * Test the successful creation of a mention event when one member mentions another in a post.
 *
 * This scenario validates the notification system for mentions within discussion board posts.
 * We must ensure linkage is correct: who performed the mention (actor), who was mentioned (target), and in which post/context this took place.
 * The scenario mimics a real workflow where a discussion post includes a mention.
 *
 * Steps:
 * 1. Create Member A (mention actor)
 * 2. Create Member B (member to be mentioned)
 * 3. Create a thread (use Member A as author)
 * 4. Create a post in that thread authored by Member A
 * 5. Create a mention event targeting Member B, done by Member A, referencing the post from step 4, with correct content_type/context
 * 6. Assert the created mention record references the correct actor_member_id, mentioned_member_id, content_type and content_id (post)
 */
export async function test_api_discussionBoard_test_create_mention_for_post_success(
  connection: api.IConnection,
) {
  // 1. Create Member A (mention actor)
  const memberA = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(32),
      display_name: RandomGenerator.name(),
      is_active: true,
      profile_image_url: null,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(memberA);

  // 2. Create Member B (member to be mentioned)
  const memberB = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(32),
      display_name: RandomGenerator.name(),
      is_active: true,
      profile_image_url: null,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(memberB);

  // 3. Create a thread authored by Member A (pick a random category UUID)
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, {
    body: {
      discussion_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.content()()(),
      is_pinned: false,
      is_closed: false,
    } satisfies IDiscussionBoardThread.ICreate,
  });
  typia.assert(thread);

  // 4. Create a post in the thread authored by Member A
  const post = await api.functional.discussionBoard.articles.posts.post(connection, {
    body: {
      discussion_board_thread_id: thread.id,
      discussion_board_member_id: memberA.id,
      body: RandomGenerator.content()()(),
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);

  // 5. Create a mention event (Member A mentions Member B in a post context)
  const now = new Date().toISOString();
  const mention = await api.functional.discussionBoard.notifications.mentions.post(connection, {
    body: {
      mentioned_member_id: memberB.id,
      actor_member_id: memberA.id,
      content_type: "post",
      content_id: post.id,
      created_at: now,
    } satisfies IDiscussionBoardMention.ICreate,
  });
  typia.assert(mention);

  // 6. Assert the created mention refers to the correct parties and context
  TestValidator.equals("mentioned_member_id matches")(mention.mentioned_member_id)(memberB.id);
  TestValidator.equals("actor_member_id matches")(mention.actor_member_id)(memberA.id);
  TestValidator.equals("content_type is post")(mention.content_type)("post");
  TestValidator.equals("content_id is post id")(mention.content_id)(post.id);
  TestValidator.predicate("created_at is valid ISO string")(!isNaN(Date.parse(mention.created_at)));
}

