/**
 * Test successfully fetching the complete detail of a mention by its ID.
 *
 * This test validates that a discussion board mention event can be accurately retrieved by its ID after creation, confirming that all returned fields match the original data. The workflow comprises member registration (both actor and mentioned), content creation, mention event creation, and retrieval/verification of the mention notification details.
 *
 * Step-by-step process:
 * 1. Register an actor member who makes the mention.
 * 2. Register a mentioned member as the mention recipient.
 * 3. Create a new thread for content context (using any random valid category id).
 * 4. Create a post in that thread, authored by the actor member, to use as the context for the mention event (content_type: 'post').
 * 5. Create the actual mention event using POST /discussionBoard/notifications/mentions, referencing the actor, mentioned member, context type, context ID (the post), and precise creation time.
 * 6. Fetch the mention event by its ID using GET /discussionBoard/notifications/mentions/{id}.
 * 7. Validate that all returned fields match the mention creation event (IDs, content_type, created_at, etc). Any mismatch should trigger test failure.
 */
export async function test_api_discussionBoard_test_get_mention_detail_success(
  connection: api.IConnection,
) {
  // 1. Register actor member
  const actorMember = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(20),
      display_name: RandomGenerator.name(),
      profile_image_url: null,
      is_active: true,
    },
  });
  typia.assert(actorMember);

  // 2. Register mentioned member
  const mentionedMember = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(20),
      display_name: RandomGenerator.name(),
      profile_image_url: null,
      is_active: true,
    },
  });
  typia.assert(mentionedMember);

  // 3. Create a new thread (category id random for test)
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, {
    body: {
      discussion_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
      is_pinned: false,
      is_closed: false,
    },
  });
  typia.assert(thread);

  // 4. Create a post in thread by the actor member
  const post = await api.functional.discussionBoard.articles.posts.post(connection, {
    body: {
      discussion_board_thread_id: thread.id,
      discussion_board_member_id: actorMember.id,
      body: RandomGenerator.content()()(),
    },
  });
  typia.assert(post);

  // 5. Create mention event
  const now = new Date().toISOString();
  const mention = await api.functional.discussionBoard.notifications.mentions.post(connection, {
    body: {
      mentioned_member_id: mentionedMember.id,
      actor_member_id: actorMember.id,
      content_type: "post",
      content_id: post.id,
      created_at: now,
    },
  });
  typia.assert(mention);

  // 6. Retrieve the mention event by ID
  const mentionDetail = await api.functional.discussionBoard.notifications.mentions.getById(connection, {
    id: mention.id,
  });
  typia.assert(mentionDetail);

  // 7. Validate all details match
  TestValidator.equals("mentioned_member_id")(mentionDetail.mentioned_member_id)(mention.mentioned_member_id);
  TestValidator.equals("actor_member_id")(mentionDetail.actor_member_id)(mention.actor_member_id);
  TestValidator.equals("content_type")(mentionDetail.content_type)(mention.content_type);
  TestValidator.equals("content_id")(mentionDetail.content_id)(mention.content_id);
  TestValidator.equals("created_at")(mentionDetail.created_at)(mention.created_at);
}

