import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IPageIDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardCategory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test listing discussion board categories with pagination and substring filtering.
 *
 * This test validates that the category listing endpoint:
 * - Returns paginated results according to the requested 'limit' and 'page',
 * - Filters categories based on a substring in their name,
 * - Accurately reports the total count of filtered categories,
 * - Correctly populates paging metadata.
 *
 * Steps:
 * 1. Create 6 categories with unique names and descriptions.
 * 2. Choose a substring from one created name as the filter.
 * 3. List categories using the substring filter, limit=2 (to enforce pagination), page=1.
 * 4. Verify:
 *    - Every returned record contains the substring in its name.
 *    - Only up to 'limit' results are returned on each page.
 *    - Pagination metadata reflects filtered total count.
 * 5. If total matching records > limit, retrieve next page and confirm all expected records are eventually returned.
 */
export async function test_api_discussionBoard_test_list_categories_with_pagination_and_filtering(
  connection: api.IConnection,
) {
  // 1. Create 6 categories with unique names/descriptions
  const count = 6;
  const categoryNames = ArrayUtil.repeat(count)(i => `Cat_${RandomGenerator.alphabets(7)}_${i}`);
  const descriptions = ArrayUtil.repeat(count)(i => `Desc_${RandomGenerator.alphabets(12)}_${i}`);

  const created: IDiscussionBoardCategory[] = [];
  for (let i = 0; i < count; ++i) {
    const c = await api.functional.discussionBoard.categories.categories.post(connection, {
      body: { name: categoryNames[i], description: descriptions[i] } satisfies IDiscussionBoardCategory.ICreate,
    });
    typia.assert(c);
    created.push(c);
  }

  // 2. Pick a non-trivial substring from one name as filter
  const filterSourceIdx = 2;
  let filterName = categoryNames[filterSourceIdx].slice(4, 8); // 4 chars from the middle
  // If by chance this produces a substring unique to only that category,
  // we still get a valid (≥1) matching set for assertions
  // Defensive: must ensure at least one match exists
  const matching = created.filter(c => c.name.includes(filterName));
  TestValidator.predicate('at least one matching category')(matching.length >= 1);

  // 3. List categories where name contains the substring, with limit=2 (page 1)
  const limit = 2;
  const resp1 = await api.functional.discussionBoard.categories.categories.patch(connection, {
    body: { name: filterName, limit, page: 1 } satisfies IDiscussionBoardCategory.IRequest,
  });
  typia.assert(resp1);
  TestValidator.equals('pagination.current')(resp1.pagination.current)(1);
  TestValidator.equals('pagination.limit')(resp1.pagination.limit)(limit);
  TestValidator.equals('pagination.records')(resp1.pagination.records)(matching.length);
  TestValidator.equals('pagination.pages')(resp1.pagination.pages)(Math.ceil(matching.length / limit));
  TestValidator.equals('data.length <= limit')(resp1.data.length <= limit)(true);
  TestValidator.predicate('all listed data match filter')(resp1.data.every(c => c.name.includes(filterName)));

  // 4. If >limit, fetch second page and aggregate all
  if (matching.length > limit) {
    const resp2 = await api.functional.discussionBoard.categories.categories.patch(connection, {
      body: { name: filterName, limit, page: 2 } satisfies IDiscussionBoardCategory.IRequest,
    });
    typia.assert(resp2);
    TestValidator.equals('pagination.current second page')(resp2.pagination.current)(2);
    const allResults = [...resp1.data, ...resp2.data];
    // May be <limit results on last page
    TestValidator.equals('aggregated results count')(allResults.length)(matching.length);
    TestValidator.predicate('all paged data match filter')(allResults.every(c => c.name.includes(filterName)));
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IPageIDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardCategory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validates listing discussion board categories including soft-deleted records.
 *
 * This test ensures that the categories listing endpoint returns both active and soft-deleted (where deleted_at is set) categories when requested. It verifies the full lifecycle:
 *
 * 1. Create several (3) categories via the POST endpoint.
 * 2. Soft delete one category using the DELETE endpoint.
 * 3. List categories using the PATCH endpoint (with/without the 'deleted_at' filter).
 * 4. Ensure:
 *    - All created categories (including the deleted one) appear in the results
 *    - The soft-deleted category has non-null deleted_at
 *    - The non-deleted categories have deleted_at null or undefined
 */
export async function test_api_discussionBoard_test_list_categories_include_soft_deleted(
  connection: api.IConnection,
) {
  // 1. Create three unique categories
  const categories: IDiscussionBoardCategory[] = [];
  for (let i = 0; i < 3; ++i) {
    const input = {
      name: `TestCategory_${RandomGenerator.alphaNumeric(8)}`,
      description: RandomGenerator.paragraph()(),
    } satisfies IDiscussionBoardCategory.ICreate;
    const created = await api.functional.discussionBoard.categories.categories.post(
      connection,
      { body: input },
    );
    typia.assert(created);
    categories.push(created);
  }

  // 2. Soft delete the second category
  const deletedCategory = categories[1];
  await api.functional.discussionBoard.categories.categories.eraseById(
    connection,
    { id: deletedCategory.id },
  );
  // No assert needed - eraseById returns void

  // 3. List all categories, including soft-deleted ones
  const output = await api.functional.discussionBoard.categories.categories.patch(
    connection,
    {
      body: { deleted_at: undefined } satisfies IDiscussionBoardCategory.IRequest,
    },
  );
  typia.assert(output);

  // 4. Verify all created categories are present, and deletion state is correct
  const listedById = new Map(output.data.map((c) => [c.id, c]));
  for (const created of categories) {
    TestValidator.predicate(`category present: ${created.name}`)(listedById.has(created.id));
  }
  // Soft-deleted category must have deleted_at set
  TestValidator.predicate("deleted category has non-null deleted_at")(
    listedById.get(deletedCategory.id)?.deleted_at !== null &&
    listedById.get(deletedCategory.id)?.deleted_at !== undefined,
  );
  // Non-deleted categories should have deleted_at null/undefined
  for (const cat of categories) {
    if (cat.id !== deletedCategory.id) {
      TestValidator.equals(`not deleted category deleted_at is null/undefined: ${cat.name}`)(
        listedById.get(cat.id)?.deleted_at
      )(null);
    }
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IPageIDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardCategory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 카테고리 description 필드의 부분 일치 검색 기능 검증
 *
 * 이 테스트는 description 필드에 특정 키워드가 포함된 카테고리를 여러 개 생성하고,
 * 해당 키워드로 부분 일치 검색을 수행했을 때, 결과가 정확히 동작하는지 검증합니다.
 *
 * 1. "통계" 키워드를 포함/미포함하는 description을 가진 카테고리를 4개 생성
 * 2. PATCH /discussionBoard/categories/categories 를 description 키워드로 검색
 * 3. 반환값의 모든 description이 "통계"를 포함하는지 확인
 * 4. 키워드를 포함한 카테고리들은 모두 결과에 반드시 존재하는지 검증
 * 5. 키워드가 없는 카테고리들은 결과에 절대 없어야 함을 추가 검증
 */
export async function test_api_discussionBoard_test_search_categories_by_description(
  connection: api.IConnection,
) {
  // 1. 키워드를 포함하거나 미포함한 각기 다른 description의 카테고리들을 사전 생성
  const keyword = "통계";
  const uniqueDescriptions = [
    `${keyword}에 관한 토론 카테고리`,
    `심층 ${keyword} 분석`,
    "생물학 카테고리",
    "정치 카테고리"
  ];

  const createdCategories: IDiscussionBoardCategory[] = [];
  for (const [idx, desc] of uniqueDescriptions.entries()) {
    const category = await api.functional.discussionBoard.categories.categories.post(
      connection,
      {
        body: {
          name: `테스트카테고리_${idx}_${Date.now()}`,
          description: desc,
        } satisfies IDiscussionBoardCategory.ICreate,
      },
    );
    typia.assert(category);
    createdCategories.push(category);
  }

  // 2. 키워드로 description 부분 일치 검색
  const searchResult = await api.functional.discussionBoard.categories.categories.patch(
    connection,
    {
      body: {
        description: keyword
      } satisfies IDiscussionBoardCategory.IRequest,
    }
  );
  typia.assert(searchResult);

  // 3. 검색 결과 description에 모두 keyword가 포함되어야 함
  for (const cat of searchResult.data) {
    TestValidator.predicate("description에 키워드가 반드시 존재해야 합니다")(
      !!cat.description && cat.description.includes(keyword),
    );
  }

  // 4. 검색 결과에 키워드를 가진 카테고리는 반드시 포함되어야 함
  const filtered = createdCategories.filter(c => c.description && c.description.includes(keyword));
  for (const cat of filtered) {
    TestValidator.predicate(`생성된 키워드 포함 카테고리(${cat.id})가 반드시 결과에 존재해야 함`)(
      searchResult.data.some(r => r.id === cat.id),
    );
  }

  // 5. 키워드 없는 카테고리는 결과에 아예 없어야 함
  const others = createdCategories.filter(c => !c.description || !c.description.includes(keyword));
  for (const cat of others) {
    TestValidator.predicate(`키워드 미포함 카테고리(${cat.id})가 결과에 없어야 함`)(
      searchResult.data.every(r => r.id !== cat.id),
    );
  }
}

