import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";

/**
 * Validate error handling for soft deletion of nonexistent or already deleted moderation reports.
 *
 * This test ensures two key business rules for the API:
 *  - Attempting to soft delete a moderation report that does not exist must return an error (404/409).
 *  - Attempting to soft delete a moderation report already deleted (deleted_at set) must also raise error (404/409).
 *
 * Step-by-step process:
 * 1. Register a member (to author the report).
 * 2. Create a thread as the report target.
 * 3. Submit a moderation report linked to the thread.
 * 4. Attempt to soft delete with a random (non-existent) report ID, verify error is thrown.
 * 5. Soft delete the existing report (expect success).
 * 6. Immediately attempt to soft delete the same report again, check error is thrown (already deleted business rule).
 */
export async function test_api_discussionBoard_test_soft_delete_nonexistent_or_already_deleted_report_returns_error(
  connection: api.IConnection,
) {
  // 1. Register a member (reporter context)
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(20),
      display_name: RandomGenerator.name(),
      profile_image_url: null,
      is_active: true,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(member);

  // 2. Create a thread (content target)
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, {
    body: {
      discussion_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(5),
      body: RandomGenerator.content()()(10),
      is_pinned: false,
      is_closed: false,
    } satisfies IDiscussionBoardThread.ICreate,
  });
  typia.assert(thread);

  // 3. Create a moderation report for the thread
  const report = await api.functional.discussionBoard.moderation.reports.post(connection, {
    body: {
      reporter_member_id: member.id,
      thread_id: thread.id,
      post_id: null,
      comment_id: null,
      reason: "테스트 신고 사유: 스팸 타겟",
      status: "pending",
    } satisfies IDiscussionBoardReport.ICreate,
  });
  typia.assert(report);

  // 4. Try to soft delete with a non-existent random id (expect error)
  await TestValidator.error("soft delete with nonexistent id throws error")(async () => {
    await api.functional.discussionBoard.moderation.reports.eraseById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    });
  });

  // 5. Soft delete the report (should succeed)
  const deleted = await api.functional.discussionBoard.moderation.reports.eraseById(connection, { id: report.id });
  typia.assert(deleted);
  TestValidator.predicate("deleted_at timestamp is present after soft delete")(!!deleted.deleted_at);

  // 6. Immediately try to soft delete again (already deleted; expect error)
  await TestValidator.error("soft delete of already deleted report throws error")(async () => {
    await api.functional.discussionBoard.moderation.reports.eraseById(connection, { id: report.id });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IdiscussionBoardModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardModerators";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardModerationLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerationLog";

/**
 * 토론 게시판 스레드에 대한 모더레이션 로그 성공 생성 플로우 검증
 *
 * - 신규 멤버 계정 생성 및 모더레이터 승격
 * - 스레드 생성 후, 모더레이터 액션 기록('hide' 또는 'delete')
 * - moderation log 반환 필드(모더레이터 id, 스레드 id, action, reason) 및 timestamp 유효성 검증
 *
 * 절차:
 * 1. 신규 멤버 계정 생성 (활성 계정)
 * 2. 해당 계정으로 모더레이터 할당
 * 3. 테스트용 토론 스레드 생성
 * 4. 모더레이터로 moderation log 생성(action, action_reason 포함)
 * 5. 반환 로그 필드(모더레이터, 스레드, action/reason, created_at 등) 검증
 */
export async function test_api_discussionBoard_moderation_moderationLogs_test_create_moderation_log_success_for_thread_action(
  connection: api.IConnection,
) {
  // 1. 신규 멤버 계정 생성
  const memberInput: IdiscussionBoardMembers.ICreate = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(24),
    display_name: RandomGenerator.name(),
    profile_image_url: null,
    is_active: true,
  };
  const member = await api.functional.discussionBoard.actors.members.post(connection, { body: memberInput });
  typia.assert(member);

  // 2. 멤버를 모더레이터로 할당
  const nowISO = new Date().toISOString();
  const moderator = await api.functional.discussionBoard.actors.moderators.post(connection, {
    body: {
      member_id: member.id,
      assigned_at: nowISO,
    } satisfies IdiscussionBoardModerators.ICreate
  });
  typia.assert(moderator);
  TestValidator.equals("moderator.member_id matches member.id")(moderator.member_id)(member.id);
  TestValidator.equals("moderator.revoked_at is null")((moderator.revoked_at ?? null))(null);

  // 3. 테스트용 토론 스레드 생성
  const threadInput: IDiscussionBoardThread.ICreate = {
    discussion_board_category_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.paragraph()(1),
    body: RandomGenerator.content()()(1),
    is_pinned: false,
    is_closed: false,
  };
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, {
    body: threadInput
  });
  typia.assert(thread);
  TestValidator.equals("thread creator matches")(thread.discussion_board_member_id)(member.id);
  TestValidator.equals("category id matches")(thread.discussion_board_category_id)(threadInput.discussion_board_category_id);

  // 4. 모더레이션 로그 생성
  const action = RandomGenerator.pick(["hide", "delete"]);
  const actionReason = "Content policy violation: spam detected";
  const moderationLogInput: IDiscussionBoardModerationLog.ICreate = {
    moderator_id: moderator.id,
    thread_id: thread.id,
    post_id: null,
    comment_id: null,
    action,
    action_reason: actionReason,
  };
  const moderationLog = await api.functional.discussionBoard.moderation.moderationLogs.post(connection, { body: moderationLogInput });
  typia.assert(moderationLog);

  // 5. 반환 필드 검증 (주요 속성/관계 등)
  TestValidator.equals("moderationLog.moderator_id matches input")(moderationLog.moderator_id)(moderationLogInput.moderator_id);
  TestValidator.equals("moderationLog.thread_id matches thread.id")(moderationLog.thread_id)(thread.id);
  TestValidator.equals("moderationLog.action matches input")(moderationLog.action)(action);
  TestValidator.equals("moderationLog.action_reason matches")(moderationLog.action_reason)(actionReason);
  TestValidator.equals("moderationLog.post_id is null")((moderationLog.post_id ?? null))(null);
  TestValidator.equals("moderationLog.comment_id is null")((moderationLog.comment_id ?? null))(null);
  // created_at timestamp이 5분 이내(시간 왜곡 없음)
  const createdAt = new Date(moderationLog.created_at).getTime();
  const skew = Math.abs(Date.now() - createdAt);
  TestValidator.predicate("created_at 5분 이내 skew 검증")(skew < 5 * 60 * 1000);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IdiscussionBoardModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardModerators";
import type { IDiscussionBoardModerationLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerationLog";

/**
 * Validate that attempting to create a moderation log with non-existent thread_id,
 * post_id, or comment_id references is properly rejected by the API.
 *
 * Context:
 * Moderation logs in a discussion board should only be associated with existing content.
 * Attempting to log moderation actions against non-existent content (invalid foreign keys)
 * poses a risk for audit integrity and can indicate either a client or service bug,
 * or possible abuse of the endpoint. This test ensures the API enforces referential integrity
 * and will respond with an error (400/404) when asked to log moderation against missing or invalid targets.
 *
 * Step-by-step process:
 * 1. Register a legitimate user/member (to later escalate to moderator).
 * 2. Escalate this member to moderator using the moderator assignment endpoint, capturing their moderator_id.
 * 3. Construct clearly non-existent UUID values for thread_id, post_id, and comment_id (not associated with any real content).
 * 4. Attempt to create moderation log records using the valid moderator_id, but with each of the invalid content reference fields filled individually (one test each for thread_id, post_id, and comment_id).
 * 5. API should reject these attempts – for each, verify that the response throws an error (e.g., status 400 or 404).
 * 6. Also check that mixing multiple invalid references in one payload is rejected.
 * 7. Confirm that error responses occur for each invalid content ID case.
 */
export async function test_api_discussionBoard_moderation_moderationLogs_test_create_moderation_log_with_invalid_content_reference_returns_error(
  connection: api.IConnection,
) {
  // Step 1: Create a valid discussion board member (future moderator)
  const memberInput: IdiscussionBoardMembers.ICreate = {
    username: RandomGenerator.alphaNumeric(10),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(32),
    display_name: RandomGenerator.name(),
    profile_image_url: null,
    is_active: true,
  };
  const member = await api.functional.discussionBoard.actors.members.post(connection, { body: memberInput });
  typia.assert(member);

  // Step 2: Assign moderator role to the member
  const moderatorInput: IdiscussionBoardModerators.ICreate = {
    member_id: member.id,
    assigned_at: new Date().toISOString(),
  };
  const moderator = await api.functional.discussionBoard.actors.moderators.post(connection, { body: moderatorInput });
  typia.assert(moderator);

  // Step 3: Create guaranteed non-existent content IDs
  const invalid_thread_id = typia.random<string & tags.Format<"uuid">>();
  const invalid_post_id = typia.random<string & tags.Format<"uuid">>();
  const invalid_comment_id = typia.random<string & tags.Format<"uuid">>();

  // Step 4-7: Test creating moderation log with each kind of invalid ID
  // Thread only
  await TestValidator.error("creating log with invalid thread_id should fail")(
    async () => {
      await api.functional.discussionBoard.moderation.moderationLogs.post(connection, {
        body: {
          moderator_id: moderator.id,
          thread_id: invalid_thread_id,
          post_id: null,
          comment_id: null,
          action: "hide",
          action_reason: "Testing with invalid thread_id",
        },
      });
    },
  );

  // Post only
  await TestValidator.error("creating log with invalid post_id should fail")(
    async () => {
      await api.functional.discussionBoard.moderation.moderationLogs.post(connection, {
        body: {
          moderator_id: moderator.id,
          thread_id: null,
          post_id: invalid_post_id,
          comment_id: null,
          action: "delete",
          action_reason: "Testing with invalid post_id",
        },
      });
    },
  );

  // Comment only
  await TestValidator.error("creating log with invalid comment_id should fail")(
    async () => {
      await api.functional.discussionBoard.moderation.moderationLogs.post(connection, {
        body: {
          moderator_id: moderator.id,
          thread_id: null,
          post_id: null,
          comment_id: invalid_comment_id,
          action: "warn",
          action_reason: "Testing with invalid comment_id",
        },
      });
    },
  );

  // Both thread and post invalid
  await TestValidator.error("creating log with invalid thread_id and post_id should fail")(
    async () => {
      await api.functional.discussionBoard.moderation.moderationLogs.post(connection, {
        body: {
          moderator_id: moderator.id,
          thread_id: invalid_thread_id,
          post_id: invalid_post_id,
          comment_id: null,
          action: "hide",
          action_reason: "Testing with multiple invalid content references",
        },
      });
    },
  );

  // All three invalid at once
  await TestValidator.error("creating log with all invalid references should fail")(
    async () => {
      await api.functional.discussionBoard.moderation.moderationLogs.post(connection, {
        body: {
          moderator_id: moderator.id,
          thread_id: invalid_thread_id,
          post_id: invalid_post_id,
          comment_id: invalid_comment_id,
          action: "edit",
          action_reason: "Testing with all invalid content refs",
        },
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IdiscussionBoardModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardModerators";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardModerationLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerationLog";
import type { IPageIDiscussionBoardModerationLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardModerationLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test the full search, filtering, and pagination capabilities of moderation logs.
 *
 * This E2E test validates that the moderation logs listing endpoint properly supports filters for moderator_id, action type, and content reference (thread_id).
 * The business goal is to ensure that auditors, admins, and compliance reviewers can reliably search for, segment, and paginate moderation actions by actor or by target entity.
 *
 * Steps covered:
 * 1. Create two members (unique identities)
 * 2. Escalate both to distinct moderators, producing two moderator_id values
 * 3. Create two threads (each by a different moderator as creator)
 * 4. Have both moderators create moderation log entries using different actions (e.g., "hide", "warn") and on different threads
 * 5. For each filter: (a) by moderator_id, (b) by action, (c) by thread_id, (d) by combination (moderator_id+action+thread_id), and (e) with limit/pagination, validate that only strictly-matching results are included in data, total/pagination metadata reflects the correct amounts, and that no record from other combinations appears.
 * 6. Assert types of all API results and thoroughly check that all response data matches the filter logic precisely.
 */
export async function test_api_discussionBoard_moderation_moderationLogs_test_list_moderation_logs_with_filter_by_moderator_and_content(connection: api.IConnection) {
  // 1. Create two unique members
  const member1 = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: RandomGenerator.alphaNumeric(8) + "@example.com",
      hashed_password: RandomGenerator.alphaNumeric(32),
      display_name: RandomGenerator.name(),
      is_active: true
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(member1);
  const member2 = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: RandomGenerator.alphaNumeric(8) + "@example.com",
      hashed_password: RandomGenerator.alphaNumeric(32),
      display_name: RandomGenerator.name(),
      is_active: true
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(member2);

  // 2. Escalate both to moderators
  const assigned_at = new Date().toISOString();
  const moderator1 = await api.functional.discussionBoard.actors.moderators.post(connection, {
    body: {
      member_id: member1.id,
      assigned_at,
    } satisfies IdiscussionBoardModerators.ICreate,
  });
  typia.assert(moderator1);
  const moderator2 = await api.functional.discussionBoard.actors.moderators.post(connection, {
    body: {
      member_id: member2.id,
      assigned_at,
    } satisfies IdiscussionBoardModerators.ICreate,
  });
  typia.assert(moderator2);

  // 3. Create two threads (by each moderator as creator)
  // Generate random dummy category uuid
  const dummy_category_1 = typia.random<string & tags.Format<"uuid">>();
  const thread1 = await api.functional.discussionBoard.articles.threads.post(connection, {
    body: {
      discussion_board_category_id: dummy_category_1,
      title: RandomGenerator.paragraph()(10),
      body: RandomGenerator.content()(5)(2),
      is_pinned: false,
      is_closed: false
    } satisfies IDiscussionBoardThread.ICreate,
  });
  typia.assert(thread1);
  const dummy_category_2 = typia.random<string & tags.Format<"uuid">>();
  const thread2 = await api.functional.discussionBoard.articles.threads.post(connection, {
    body: {
      discussion_board_category_id: dummy_category_2,
      title: RandomGenerator.paragraph()(10),
      body: RandomGenerator.content()(5)(2),
      is_pinned: false,
      is_closed: false
    } satisfies IDiscussionBoardThread.ICreate,
  });
  typia.assert(thread2);

  // 4. Log moderation actions: moderator1 logs "hide" on thread1, moderator2 logs "warn" on thread2
  const action1 = "hide";
  const log1 = await api.functional.discussionBoard.moderation.moderationLogs.post(connection, {
    body: {
      moderator_id: moderator1.id,
      thread_id: thread1.id,
      action: action1,
    } satisfies IDiscussionBoardModerationLog.ICreate,
  });
  typia.assert(log1);
  const action2 = "warn";
  const log2 = await api.functional.discussionBoard.moderation.moderationLogs.post(connection, {
    body: {
      moderator_id: moderator2.id,
      thread_id: thread2.id,
      action: action2,
    } satisfies IDiscussionBoardModerationLog.ICreate,
  });
  typia.assert(log2);

  // 5a. Filter: moderator_id = moderator1.id
  const res_by_mod1 = await api.functional.discussionBoard.moderation.moderationLogs.patch(connection, {
    body: {
      moderator_id: moderator1.id
    } satisfies IDiscussionBoardModerationLog.IRequest,
  });
  typia.assert(res_by_mod1);
  for (const entry of res_by_mod1.data) {
    TestValidator.equals("moderator_id only moderator1")(entry.moderator_id)(moderator1.id);
  }

  // 5b. Filter: action = "warn"
  const res_by_action_warn = await api.functional.discussionBoard.moderation.moderationLogs.patch(connection, {
    body: {
      action: action2
    } satisfies IDiscussionBoardModerationLog.IRequest,
  });
  typia.assert(res_by_action_warn);
  for (const entry of res_by_action_warn.data) {
    TestValidator.equals("action only warn")(entry.action)(action2);
  }

  // 5c. Filter: thread_id = thread1.id
  const res_by_thread1 = await api.functional.discussionBoard.moderation.moderationLogs.patch(connection, {
    body: {
      thread_id: thread1.id
    } satisfies IDiscussionBoardModerationLog.IRequest,
  });
  typia.assert(res_by_thread1);
  for (const entry of res_by_thread1.data) {
    TestValidator.equals("thread_id only thread1")(entry.thread_id)(thread1.id);
  }

  // 5d. Pagination: mod1, limit=1
  const res_mod1_limit = await api.functional.discussionBoard.moderation.moderationLogs.patch(connection, {
    body: {
      moderator_id: moderator1.id,
      limit: 1
    } satisfies IDiscussionBoardModerationLog.IRequest,
  });
  typia.assert(res_mod1_limit);
  TestValidator.equals("pagination limit 1")(res_mod1_limit.pagination.limit)(1);
  TestValidator.predicate("returns 1 or fewer records")(res_mod1_limit.data.length <= 1);

  // 5e. Combo: moderator_id + action + thread_id
  const combo = await api.functional.discussionBoard.moderation.moderationLogs.patch(connection, {
    body: {
      moderator_id: moderator1.id,
      action: action1,
      thread_id: thread1.id
    } satisfies IDiscussionBoardModerationLog.IRequest,
  });
  typia.assert(combo);
  for (const entry of combo.data) {
    TestValidator.equals("moderator combo")(entry.moderator_id)(moderator1.id);
    TestValidator.equals("action combo")(entry.action)(action1);
    TestValidator.equals("thread combo")(entry.thread_id)(thread1.id);
  }

  // 6. Negative: ensure no extraneous records in filtered results
  for (const entry of res_by_mod1.data) {
    TestValidator.equals("filtered by moderator1")(entry.moderator_id)(moderator1.id);
  }
  for (const entry of res_by_action_warn.data) {
    TestValidator.equals("filtered by action warn")(entry.action)(action2);
  }
  for (const entry of res_by_thread1.data) {
    TestValidator.equals("filtered by thread1")(entry.thread_id)(thread1.id);
  }
  for (const entry of combo.data) {
    TestValidator.equals("moderator combo")(entry.moderator_id)(moderator1.id);
    TestValidator.equals("action combo")(entry.action)(action1);
    TestValidator.equals("thread combo")(entry.thread_id)(thread1.id);
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
