/**
 * Validate that attempting to update a category with a non-existent UUID results in a 404 error.
 *
 * This test ensures the update endpoint (PUT /discussionBoard/categories/categories/:id) returns a Not Found error when given a UUID that does not correspond to any existing category. This guards against unintended creation or silent failure on missing categories.
 *
 * Steps:
 * 1. Generate a random UUID that is extremely unlikely to exist in the system (since we're not creating any category during this test).
 * 2. Attempt to update a category using the generated UUID and any update payload.
 * 3. Assert that a 404 error is thrown by the API (not a silent failure or other error code).
 */
export async function test_api_discussionBoard_test_update_non_existent_category(
  connection: api.IConnection,
) {
  // 1. Generate a random (nonexistent) UUID
  const randomCategoryId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();

  // 2. Prepare an arbitrary valid update payload
  const updatePayload: IDiscussionBoardCategory.IUpdate = {
    name: "Nonexistent Category",
    description: "Trying to update a category that does not exist.",
  };

  // 3. Attempt to update and assert that a 404 error is thrown
  await TestValidator.error("should throw 404 Not Found")(
    async () => {
      await api.functional.discussionBoard.categories.categories.putById(
        connection,
        {
          id: randomCategoryId,
          body: updatePayload,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";

/**
 * Validates that category immutable/system fields (id, created_at, updated_at, deleted_at)
 * cannot be updated via the API. Only name and description are allowed to change.
 *
 * This test covers both negative (malicious/invalid update) and positive (normal update)
 * cases for the PUT /discussionBoard/categories/categories/{id} endpoint.
 *
 * Steps:
 * 1. Create a new category for testing
 * 2. Attempt to update immutable fields (id, created_at, etc.) via PUT (using cast or any)
 *    - Expect an error or that the system ignores/filters these fields
 * 3. After the invalid attempt, perform a legitimate name/description update and verify change
 * 4. Check that all fields except name/description remained unchanged
 */
export async function test_api_discussionBoard_test_update_category_with_immutable_field(
  connection: api.IConnection,
) {
  // 1. Create a category to test updates on
  const createInput: IDiscussionBoardCategory.ICreate = {
    name: RandomGenerator.alphabets(8),
    description: RandomGenerator.paragraph()(),
  };
  const original = await api.functional.discussionBoard.categories.categories.post(
    connection,
    {
      body: createInput,
    },
  );
  typia.assert(original);

  // 2. Try to maliciously update immutable fields (id, created_at, updated_at, deleted_at)
  const forbiddenUpdate: any = {
    name: RandomGenerator.alphabets(8),
    id: typia.random<string & tags.Format<"uuid">>(),
    created_at: typia.random<string & tags.Format<"date-time">>(),
    updated_at: typia.random<string & tags.Format<"date-time">>(),
    deleted_at: null,
    description: RandomGenerator.paragraph()(),
  };
  await TestValidator.error("Updating immutable fields must fail or be filtered")(
    async () => {
      await api.functional.discussionBoard.categories.categories.putById(
        connection,
        {
          id: original.id,
          body: forbiddenUpdate,
        },
      );
    },
  );

  // 3. Now do a valid update, only name/description
  const updateInput: IDiscussionBoardCategory.IUpdate = {
    name: RandomGenerator.alphabets(12),
    description: RandomGenerator.paragraph()(),
  };
  const updated = await api.functional.discussionBoard.categories.categories.putById(
    connection,
    {
      id: original.id,
      body: updateInput,
    },
  );
  typia.assert(updated);

  // 4. Assert that only allowed fields have changed
  TestValidator.equals("id stays same")(updated.id)(original.id);
  TestValidator.equals("created_at stays same")(updated.created_at)(original.created_at);
  TestValidator.equals("deleted_at stays same")(
    updated.deleted_at,
  )(original.deleted_at ?? null);
  TestValidator.equals("name updated")(updated.name)(updateInput.name);
  TestValidator.equals("description updated")(updated.description)(updateInput.description);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IPageIDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardCategory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test soft deleting an existing category by ID.
 *
 * Business context:
 * - Categories help organize discussion threads and posts.
 * - Soft delete should mark the category deleted (set deleted_at), but not erase the record.
 * - Soft-deleted categories should be inaccessible for new assignments and hidden from normal category listings.
 *
 * Test steps:
 * 1. Create a category using the POST endpoint, saving the returned ID.
 * 2. List categories (PATCH) and verify the new category appears and deleted_at is null.
 * 3. Soft delete the category using DELETE by ID.
 * 4. List categories again with deleted_at filter unset or false, and verify the category no longer appears.
 * 5. List categories with deleted_at=true filter and verify the deleted category appears and deleted_at is set (not null).
*/
export async function test_api_discussionBoard_categories_categories_test_soft_delete_category_success(
  connection: api.IConnection,
) {
  // 1. Create a category
  const name = RandomGenerator.alphaNumeric(8);
  const description = RandomGenerator.paragraph()();
  const created: IDiscussionBoardCategory = await api.functional.discussionBoard.categories.categories.post(
    connection,
    {
      body: {
        name,
        description,
      } satisfies IDiscussionBoardCategory.ICreate,
    }
  );
  typia.assert(created);
  TestValidator.equals("category name matches")(created.name)(name);
  TestValidator.equals("category description matches")(created.description)(description);
  TestValidator.equals("category is not soft deleted")(created.deleted_at)(null);

  // 2. List all categories and verify the new one appears
  const page1 = await api.functional.discussionBoard.categories.categories.patch(
    connection,
    { body: { name } satisfies IDiscussionBoardCategory.IRequest }
  );
  typia.assert(page1);
  const found1 = page1.data.find(cat => cat.id === created.id);
  TestValidator.predicate("created category found in list")(!!found1);
  TestValidator.equals("category is not soft deleted")(found1?.deleted_at)(null);

  // 3. Soft delete the category
  await api.functional.discussionBoard.categories.categories.eraseById(
    connection,
    { id: created.id },
  );

  // 4. List categories (active only, deleted_at:false or omitted)
  const page2 = await api.functional.discussionBoard.categories.categories.patch(
    connection,
    { body: { name } satisfies IDiscussionBoardCategory.IRequest }
  );
  typia.assert(page2);
  const found2 = page2.data.find(cat => cat.id === created.id);
  TestValidator.equals("category is not in active categories after delete")(found2)(undefined);

  // 5. List categories with deleted_at=true to fetch soft-deleted ones
  const page3 = await api.functional.discussionBoard.categories.categories.patch(
    connection,
    { body: { name, deleted_at: true } satisfies IDiscussionBoardCategory.IRequest }
  );
  typia.assert(page3);
  const found3 = page3.data.find(cat => cat.id === created.id);
  TestValidator.predicate("deleted category is found when including deleted_at=true")(!!found3);
  TestValidator.predicate("deleted_at field is set (category is soft deleted)")(!!found3?.deleted_at);
}

