import type { IDiscussionBoardSearchHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSearchHistory";

/**
 * Validate creation of a discussion board search history record by a registered member.
 *
 * This test ensures that authenticated members can successfully record their search activities—
 * supporting tracking, analytics, and personalization features. The test verifies all required
 * schema fields are properly persisted, and optional properties are handled as expected.
 *
 * Steps:
 * 1. Create a new unique discussion board member (for actor_id) and confirm response.
 * 2. Prepare a valid search history record using the member's id for actor_id, supplying
 *    valid keyword and created_at values (optionally, supply filters and search_context).
 * 3. Invoke the searchHistory creation API endpoint as the authenticated member.
 * 4. Verify the response matches the request—the persisted search history record contains
 *    the same actor_id, keyword, created_at, and any supplied optionals (filters/context).
 */
export async function test_api_discussionBoard_test_create_search_history_with_valid_parameters(
  connection: api.IConnection,
) {
  // 1. Create a new discussion board member to use as actor (search initiator)
  const memberInput: IdiscussionBoardMembers.ICreate = {
    username: RandomGenerator.alphaNumeric(10),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(16),
    display_name: RandomGenerator.name(),
    profile_image_url: null,
    is_active: true,
  };
  const member = await api.functional.discussionBoard.actors.members.post(connection, { body: memberInput });
  typia.assert(member);

  // 2. Prepare valid search history input for this member
  const keyword = RandomGenerator.alphaNumeric(8);
  const created_at = new Date().toISOString();
  const searchHistoryInput: IDiscussionBoardSearchHistory.ICreate = {
    actor_id: member.id,
    keyword,
    filters: JSON.stringify({ tags: ["interesting", "test"] }),
    search_context: "thread_list",
    created_at,
  };

  // 3. Create the search history record
  const history = await api.functional.discussionBoard.search.searchHistories.post(connection, { body: searchHistoryInput });
  typia.assert(history);

  // 4. Verify response fields
  TestValidator.equals("actor_id matches")(history.actor_id)(member.id);
  TestValidator.equals("keyword matches")(history.keyword)(keyword);
  TestValidator.equals("filters matches")(history.filters)(searchHistoryInput.filters);
  TestValidator.equals("search_context matches")(history.search_context)(searchHistoryInput.search_context);
  TestValidator.equals("created_at matches")(history.created_at)(created_at);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
