    });
  });

  // 3. Try creating a search history entry omitting 'keyword'
  TestValidator.error("omitting keyword should result in validation error")(async () => {
    await api.functional.discussionBoard.search.searchHistories.post(connection, {
      body: {
        actor_id: member.id,
        // missing keyword
        created_at: new Date().toISOString(),
      } as any,
    });
  });

  // 4. Try omitting both required fields
  TestValidator.error("omitting both actor_id and keyword should result in validation error")(async () => {
    await api.functional.discussionBoard.search.searchHistories.post(connection, {
      body: {
        // missing actor_id and keyword
        created_at: new Date().toISOString(),
      } as any,
    });
  });
