import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardSearchHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSearchHistory";

/**
 * Validates referential integrity for actor_id on search history creation.
 *
 * Attempts to create a new search history entry as a member using a non-existent or deleted actor_id (UUID).
 * The API must return an error (404 Not Found or validation error), confirming it enforces referential integrity:
 * no search history should be created for non-existent users/actors.
 *
 * Test Steps:
 * 1. Generate a random UUID as an invalid actor_id.
 * 2. Construct a valid search history payload, but with the invalid actor_id.
 * 3. Attempt to create the search history entry -- expect the API to throw an error (no success on invalid actor).
 * 4. Confirm that the API enforces the integrity constraint by not allowing history creation with an invalid actor_id.
 */
export async function test_api_discussionBoard_test_create_search_history_with_invalid_actor_id(
  connection: api.IConnection,
) {
