/**
 * Verify that a non-author member cannot soft delete another member's post (authorization test).
 *
 * Steps:
 * 1. Register two distinct discussion board members: memberA (post author) and memberB (unauthorized actor).
 * 2. MemberA creates a new thread in a random category, with dummy title and body.
 * 3. MemberA creates a post in that thread (as the post to be protected).
 * 4. MemberB attempts to soft-delete (eraseById) memberA's post using the post's id.
 * 5. Verify the API throws an authorization error (TestValidator.error).
 * 6. Re-extract the post to confirm that is unmodified (not soft-deleted, deleted_at is still null, body unchanged).
 */
export async function test_api_discussionBoard_test_soft_delete_post_by_non_author_fails(
  connection: api.IConnection,
) {
  // 1. Register Member A (the author of the target post)
  const memberA_signup = {
    username: RandomGenerator.alphabets(10),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(16),
    display_name: RandomGenerator.name(),
    is_active: true,
  } satisfies IdiscussionBoardMembers.ICreate;
  const memberA = await api.functional.discussionBoard.actors.members.post(connection, { body: memberA_signup });
  typia.assert(memberA);

  // 2. Register Member B (will attempt unauthorized delete)
  const memberB_signup = {
    username: RandomGenerator.alphabets(10),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(16),
    display_name: RandomGenerator.name(),
    is_active: true,
  } satisfies IdiscussionBoardMembers.ICreate;
  const memberB = await api.functional.discussionBoard.actors.members.post(connection, { body: memberB_signup });
  typia.assert(memberB);

  // 3. Member A creates a thread
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, {
    body: {
      discussion_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
      is_pinned: false,
      is_closed: false,
    } satisfies IDiscussionBoardThread.ICreate,
  });
  typia.assert(thread);

  // 4. Member A creates a post in the thread
  const post = await api.functional.discussionBoard.articles.posts.post(connection, {
    body: {
      discussion_board_thread_id: thread.id,
      discussion_board_member_id: memberA.id,
      body: RandomGenerator.content()()(),
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);
  TestValidator.equals("initial: not deleted")(post.deleted_at)(null);

  // 5. Member B attempts to soft-delete Member A's post
  TestValidator.error("Non-author cannot delete another user's post")(
    async () => {
      // No authentication context switch is possible, so this simulates an unauthorized attempt per scenario intent
      await api.functional.discussionBoard.articles.posts.eraseById(
        connection,
        { id: post.id },
      );
    },
  );

  // 6. Confirm post still present and not deleted (refresh not possible without GET API, so use previous post state)
  TestValidator.equals("still not deleted after failed delete")(post.deleted_at)(null);
}

