/**
 * Validate fetching details of an active comment by its UUID for a registered member.
 *
 * Ensures a realistic full workflow:
 * 1. Register a member (the future comment author)
 * 2. Create a thread with the member as the author
 * 3. Create a post within that thread by the same member
 * 4. Add a comment to that post, authored by the member
 * 5. Fetch the comment by ID
 *    - Assert all fields are present per schema
 *    - Validate the author, body content, parent-child linkage, and that deleted_at is null (active)
 */
export async function test_api_discussionBoard_test_get_comment_detail_success(
  connection: api.IConnection,
) {
  // 1. Register a member
  const memberInput: IdiscussionBoardMembers.ICreate = {
    username: RandomGenerator.alphabets(10),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(16),
    display_name: RandomGenerator.name(),
    profile_image_url: null,
    is_active: true,
  };
  const member = await api.functional.discussionBoard.actors.members.post(connection, { body: memberInput });
  typia.assert(member);

  // 2. Create a thread with the member as the author
  // Thread must reference a (random) category; we provide a new UUID for category linkage
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const threadInput: IDiscussionBoardThread.ICreate = {
    discussion_board_category_id: categoryId,
    title: RandomGenerator.paragraph()(1),
    body: RandomGenerator.content()()(),
    is_pinned: false,
    is_closed: false,
  };
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, { body: { ...threadInput } });
  typia.assert(thread);

  // 3. Create a post within the thread by this member
  const postInput: IDiscussionBoardPost.ICreate = {
    discussion_board_thread_id: thread.id,
    discussion_board_member_id: member.id,
    body: RandomGenerator.content()()(),
  };
  const post = await api.functional.discussionBoard.articles.posts.post(connection, { body: postInput });
  typia.assert(post);

  // 4. Add a comment to the post, authored by this member
  const commentBody = RandomGenerator.paragraph()(1);
  const commentInput: IDiscussionBoardComment.ICreate = {
    discussion_board_post_id: post.id,
    discussion_board_member_id: member.id,
    body: commentBody,
    parent_id: null,
  };
  const comment = await api.functional.discussionBoard.articles.comments.post(connection, { body: commentInput });
  typia.assert(comment);

  // 5. Fetch the comment by ID
  const fetched = await api.functional.discussionBoard.articles.comments.getById(connection, { id: comment.id });
  typia.assert(fetched);

  // Validate all fields
  TestValidator.equals("id matches")(fetched.id)(comment.id);
  TestValidator.equals("discussion_board_post_id matches")(fetched.discussion_board_post_id)(comment.discussion_board_post_id);
  TestValidator.equals("author matches")(fetched.discussion_board_member_id)(member.id);
  TestValidator.equals("body matches")(fetched.body)(commentBody);
  TestValidator.equals("deleted_at is null (active comment)")(fetched.deleted_at)(null);
  TestValidator.predicate("parent_id matches")(fetched.parent_id === null);
  TestValidator.predicate("is_edited is boolean")(typeof fetched.is_edited === "boolean");
  TestValidator.predicate("created_at format")(typeof fetched.created_at === "string" && !!Date.parse(fetched.created_at));
  TestValidator.predicate("updated_at format")(typeof fetched.updated_at === "string" && !!Date.parse(fetched.updated_at));
}

