import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IdiscussionBoardModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardModerators";
import type { IModerationWarning } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerationWarning";

/**
 * Validate a moderator can update allowed fields of an existing warning record on the discussion board.
 *
 * Business context:
 * This test ensures that a moderator can update editable fields (warning_type, message, expires_at)
 * of an existing warning record, while immutable fields (id, deleted_at) remain unchanged.
 *
 * Step-by-step process:
 * 1. Create a regular member (collect member_id for later steps)
 * 2. Assign moderator role to the created member (collect moderator_id)
 * 3. Issue a warning to the member as the new moderator
 * 4. Update the warning record's allowed fields (warning_type, message, expires_at)
 * 5. Assert that updatable fields have changed, and immutable fields remain the same
 */
export async function test_api_discussionBoard_moderation_warnings_test_update_warning_record_with_valid_fields(
  connection: api.IConnection,
) {
  // 1. Create a member to be warned
  const memberInput: IdiscussionBoardMembers.ICreate = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(20),
    display_name: RandomGenerator.name(),
    profile_image_url: null,
    is_active: true,
  };
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: memberInput,
  });
  typia.assert(member);

  // 2. Assign moderator role to the created member
  const assignmentTime = new Date().toISOString();
  const moderatorInput: IdiscussionBoardModerators.ICreate = {
    member_id: member.id,
    assigned_at: assignmentTime,
  };
  const moderator = await api.functional.discussionBoard.actors.moderators.post(connection, {
    body: moderatorInput,
  });
  typia.assert(moderator);

  // 3. Issue a warning for that member as this moderator
  const warningCreateInput: IModerationWarning.ICreate = {
    member_id: member.id,
    moderator_id: moderator.id,
    warning_type: "spam",
    message: "Initial warning for update test.",
    created_at: new Date().toISOString(),
    expires_at: null,
  };
  const warning = await api.functional.discussionBoard.moderation.warnings.post(connection, {
    body: warningCreateInput,
  });
  typia.assert(warning);

  // 4. Update the warning fields (warning_type, message, expires_at)
  const newExpiresAt = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(); // +1 week
  const warningUpdateInput: IModerationWarning.IUpdate = {
    warning_type: "harassment",
    message: "Moderator has updated this warning for further infractions.",
    expires_at: newExpiresAt,
  };
  const updatedWarning = await api.functional.discussionBoard.moderation.warnings.putById(connection, {
    id: warning.id,
    body: warningUpdateInput,
  });
  typia.assert(updatedWarning);

  // 5. Assert updatable fields changed, and immutable fields are unchanged
  TestValidator.equals("warning_type updated")(updatedWarning.warning_type)(warningUpdateInput.warning_type);
  TestValidator.equals("message updated")(updatedWarning.message)(warningUpdateInput.message);
  TestValidator.equals("expires_at updated")(updatedWarning.expires_at)(warningUpdateInput.expires_at);

  TestValidator.equals("id remains unchanged")(updatedWarning.id)(warning.id);
  TestValidator.equals("deleted_at unchanged")(updatedWarning.deleted_at)(warning.deleted_at);
}

