 * 실제 업데이트는 허용된 필드(warning_type, message, expires_at)로만 이루어짐을 검증합니다.
 *
 * 비즈니스 목적:
 *   - 경고는 오직 허용된 필드만 업데이트할 수 있고, id나 deleted_at 등의 필드는 API/DTO 스키마상 타입 수준에서 전달 불가합니다.
 *   - 따라서 타입 시스템으로 금지된 필드는 런타임 또는 컴파일 타임에 걸러지고, E2E에서는 타입이 허용된 필드 중심 정상 케이스만 검증합니다.
 *
 * 테스트 흐름:
 * 1. 멤버 생성
 * 2. 모더레이터 권한 부여
 * 3. 해당 멤버에 대한 경고 발급
 * 4. 허용된 필드(warning_type, message, expires_at)만으로 update → 정상적으로 반영됨 검증
 */
export async function test_api_discussionBoard_test_update_warning_record_with_disallowed_fields(
  connection: api.IConnection,
) {
  // 1. 유효한 멤버 생성
  const memberInput = {
    username: RandomGenerator.alphaNumeric(10),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(32),
    display_name: RandomGenerator.name(),
    is_active: true,
    profile_image_url: null,
  } satisfies IdiscussionBoardMembers.ICreate;
  const member = await api.functional.discussionBoard.actors.members.post(connection, { body: memberInput });
  typia.assert(member);

  // 2. 모더레이터 권한 할당
  const moderatorInput = {
    member_id: member.id,
    assigned_at: new Date().toISOString(),
  } satisfies IdiscussionBoardModerators.ICreate;
  const moderator = await api.functional.discussionBoard.actors.moderators.post(connection, { body: moderatorInput });
  typia.assert(moderator);

  // 3. 경고장 발급
  const warningInput = {
    member_id: member.id,
    moderator_id: moderator.id,
    warning_type: "spam",
    message: "Do not post spam messages.",
    created_at: new Date().toISOString(),
    expires_at: null,
  } satisfies IModerationWarning.ICreate;
  const warning = await api.functional.discussionBoard.moderation.warnings.post(connection, { body: warningInput });
  typia.assert(warning);

  // 4. 허용 필드만 update 시 정상 수정됨
  const updateBody = {
    warning_type: "harassment",
    message: "Harassment - 2nd warning.",
    expires_at: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(),
  } satisfies IModerationWarning.IUpdate;
  const updated = await api.functional.discussionBoard.moderation.warnings.putById(connection, {
    id: warning.id,
    body: updateBody,
  });
  typia.assert(updated);
  TestValidator.equals("warning_type 변경됨")(updated.warning_type)(updateBody.warning_type);
  TestValidator.equals("message 변경됨")(updated.message)(updateBody.message);
  TestValidator.equals("expires_at 변경됨")(updated.expires_at)(updateBody.expires_at);
}

