import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IdiscussionBoardModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardModerators";
import type { IModerationBan } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerationBan";
import type { IPageIModerationBan } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIModerationBan";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate listing and filtering of ban records by a moderator.
 *
 * This test ensures that, after creating multiple members and assigning moderator privileges, bans can be imposed on various users. It then verifies that retrieval via the /discussionBoard/moderation/bans PATCH endpoint accurately filters bans using different criteria—member_id, permanence, substring in the ban reason, and temporal windows. At least one expired or overlapping ban should be present to validate date filtering and result logic. Pagination correctness is also checked.
 *
 * Step-by-step process:
 * 1. Create several (e.g., 3+) unique member accounts
 * 2. Assign moderator privileges to a member (the "moderator")
 * 3. Issue several bans (temporary, permanent, with overlapping times, some expired) to cover filter cases
 * 4. As moderator, retrieve bans filtered by:
 *    - member_id (for a known banned member)
 *    - permanent=true (permanent bans only)
 *    - permanent=false (temporary bans only)
 *    - ban_reason substring search
 *    - created_at_from/created_at_to to check time-based filters (and that expired bans can be found)
 *    - combinations of the above
 *    - Use pagination (limit/count) to check total/part returns
 * 5. For each filter, ensure only matching bans are returned (by examining their fields versus expected criteria)
 */
export async function test_api_discussionBoard_test_list_bans_with_filtering_and_pagination(connection: api.IConnection) {
  // 1. Create several members
  const memberList: IdiscussionBoardMembers[] = await ArrayUtil.asyncRepeat(4)(async () => {
    const input: IdiscussionBoardMembers.ICreate = {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(32),
      display_name: RandomGenerator.name(),
      profile_image_url: null,
      is_active: true,
    };
    const member = await api.functional.discussionBoard.actors.members.post(connection, { body: input });
    typia.assert(member);
    return member;
  });

  // 2. Assign moderator privileges to the first created member
  const now = new Date();
  const moderatorMember = memberList[0];
  const moderatorAssignment = await api.functional.discussionBoard.actors.moderators.post(connection, {
    body: {
      member_id: moderatorMember.id,
      assigned_at: now.toISOString(),
    },
  });
  typia.assert(moderatorAssignment);

  // 3. Issue bans: at least one expired, one permanent, and overlapping
  const bans: IModerationBan[] = [];
  const banSeed = [
    // Expired ban: second member
    {
      member: memberList[1],
      reason: "Spamming links",
      permanent: false,
      expiresOffset: -3, // Expired 3 days ago
    },
    // Active temporary ban: third member
    {
      member: memberList[2],
      reason: "Offensive language",
      permanent: false,
      expiresOffset: 2, // Will expire in 2 days
    },
    // Permanent ban: fourth member
    {
      member: memberList[3],
      reason: "Severe policy violation",
      permanent: true,
      expiresOffset: null,
    },
    // Overlapping ban: third member again
    {
      member: memberList[2],
      reason: "Additional ban for repeated issues",
      permanent: false,
      expiresOffset: 5, // Will expire in 5 days
    },
  ];

  for (const banDesc of banSeed) {
    const expires_at = banDesc.permanent
      ? null
      : new Date(now.getTime() + (banDesc.expiresOffset ?? 0) * 24 * 60 * 60 * 1000).toISOString();
    const ban = await api.functional.discussionBoard.moderation.bans.post(connection, {
      body: {
        member_id: banDesc.member.id,
        moderator_id: moderatorAssignment.id,
        ban_reason: banDesc.reason,
        permanent: banDesc.permanent,
        expires_at,
      },
    });
    typia.assert(ban);
    bans.push(ban);
  }

  // Helper: get all bans for reference
  const allBans = bans;

  // 4. Filter: by member_id (third member, who has 2 bans)
  let response = await api.functional.discussionBoard.moderation.bans.patch(connection, {
    body: { member_id: memberList[2].id },
  });
  typia.assert(response);
  TestValidator.predicate("correct bans for member_id")(response.data.every(ban => ban.member_id === memberList[2].id));
  TestValidator.equals("ban count for member_id")(response.data.length)(2);

  // 5. Filter: permanent=true
  response = await api.functional.discussionBoard.moderation.bans.patch(connection, {
    body: { permanent: true },
  });
  typia.assert(response);
  TestValidator.predicate("all permanent")(response.data.every(ban => ban.permanent === true));

  // 6. Filter: permanent=false
  response = await api.functional.discussionBoard.moderation.bans.patch(connection, {
    body: { permanent: false },
  });
  typia.assert(response);
  TestValidator.predicate("all temporary")(response.data.every(ban => ban.permanent === false));

  // 7. Filter: reason substring search (case insensitive)
  const reasonSubstr = "policy";
  response = await api.functional.discussionBoard.moderation.bans.patch(connection, {
    body: { ban_reason: reasonSubstr },
  });
  typia.assert(response);
  TestValidator.predicate("ban_reason substring")(response.data.every(ban => ban.ban_reason.toLowerCase().includes(reasonSubstr)));

  // 8. Filter: created_at_from (should get all bans as they're just created)
  response = await api.functional.discussionBoard.moderation.bans.patch(connection, {
    body: { created_at_from: now.toISOString() },
  });
  typia.assert(response);
  TestValidator.predicate("all bans created after from")(response.data.every(ban => ban.created_at >= now.toISOString()));

  // 9. Filter: created_at_to (using now + 1 min, should include all)
  const plusOneMin = new Date(now.getTime() + 60 * 1000).toISOString();
  response = await api.functional.discussionBoard.moderation.bans.patch(connection, {
    body: { created_at_to: plusOneMin },
  });
  typia.assert(response);
  TestValidator.predicate("all bans created before to")(response.data.every(ban => ban.created_at <= plusOneMin));

  // 10. Pagination: set limit=2, check only 2 returned, total matches
  // The DTO for pagination expects current and limit; only filters are allowed in request, return contains pagination
  response = await api.functional.discussionBoard.moderation.bans.patch(connection, {
    body: {},
  });
  typia.assert(response);
  const totalRecords = response.pagination.records;
  response = await api.functional.discussionBoard.moderation.bans.patch(connection, {
    body: {},
  });
  typia.assert(response);
  TestValidator.equals("total records")(response.data.length)(Math.min(response.data.length, totalRecords));
}

