import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";

/**
 * Test that updating a discussion board thread strictly enforces schema validation and rejects or ignores non-schema fields.
 *
 * Ensures that sending extra (invalid/non-schema) properties in the update payload either results in a validation error or those properties are silently ignored—and are never included in the updated discussion thread entity.
 *
 * Steps:
 * 1. Create a new member (author).
 * 2. Create a new discussion board category.
 * 3. Create a new thread as that member in the created category.
 * 4. Attempt to update the thread with both valid and extraneous fields in the update payload.
 * 5. Confirm the API either throws a validation error or ignores extra fields; extra fields must not appear in the update result.
 * 6. Assert the result is correct: error for strict validation, or extra fields omitted on success.
 */
export async function test_api_discussionBoard_test_update_thread_with_non_schema_fields_rejected(
  connection: api.IConnection,
) {
  // 1. Create a member (thread author)
  const member = await api.functional.discussionBoard.actors.members.post(
    connection,
    {
      body: {
        username: RandomGenerator.alphabets(8),
        email: typia.random<string & tags.Format<"email">>(),
        hashed_password: RandomGenerator.alphaNumeric(32),
        display_name: RandomGenerator.name(),
        profile_image_url: null,
        is_active: true,
      } satisfies IdiscussionBoardMembers.ICreate,
    },
  );
  typia.assert(member);

  // 2. Create a category
  const category = await api.functional.discussionBoard.categories.categories.post(
    connection,
    {
      body: {
        name: RandomGenerator.alphabets(16),
        description: RandomGenerator.paragraph()(),
      } satisfies IDiscussionBoardCategory.ICreate,
    },
  );
  typia.assert(category);

  // 3. Create a new thread in this category
  const thread = await api.functional.discussionBoard.articles.threads.post(
    connection,
    {
      body: {
        discussion_board_category_id: category.id,
        title: "Initial Title",
        body: "Initial body text.",
        is_pinned: false,
        is_closed: false,
      } satisfies IDiscussionBoardThread.ICreate,
    },
  );
  typia.assert(thread);

  // 4. Attempt update with extra fields (non-schema fields injected)
  const validUpdatePayload: IDiscussionBoardThread.IUpdate = {
    title: "Updated title",
    body: "Updated body.",
  };
  // Inject illegal fields
  const updatePayload = {
    ...validUpdatePayload,
    nonexistent_field: "should not be accepted",
    fakeProp: 9876,
  };

  let updateResult: IDiscussionBoardThread | null = null;
  let updateError: unknown = null;
  try {
    // Test intentional type-violation: pass extra fields as-if part of the DTO
    updateResult = await api.functional.discussionBoard.articles.threads.putById(
      connection,
      {
        id: thread.id,
        body: updatePayload as any, // purposely break types for non-schema fields
      },
    );
  } catch (error) {
    updateError = error;
  }

  // 5 & 6. Assert outcome (strict error OR silent ignore)—never allow extraneous fields on success
  if (updateError) {
    TestValidator.predicate("error thrown for extra fields")(!!updateError);
  } else if (updateResult) {
    typia.assert(updateResult);
    TestValidator.equals("no extra field in updated thread")(
      (updateResult as any).nonexistent_field,
    )(undefined);
    TestValidator.equals("no extra field in updated thread")(
      (updateResult as any).fakeProp,
    )(undefined);
  } else {
    TestValidator.error("API must either throw or ignore extra fields")(
      () => {
        throw new Error("No result and no error thrown.");
      },
    );
  }
}

