import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";

/**
 * Validate that creating a post using a non-existent thread UUID fails with an error response.
 *
 * This test checks the API's error handling when a client attempts to create a post while referencing a thread (discussion_board_thread_id) that does not exist in the system. The test ensures that the endpoint does not allow the creation of orphaned posts and returns a proper runtime error when the thread UUID is invalid or missing in the system.
 *
 * Steps:
 * 1. Create a discussion board member, who will be the author of the post.
 * 2. Prepare a random UUID to use as the thread ID, ensuring that no thread with this ID exists (do not create any thread with this ID).
 * 3. Attempt to create a post with the author's member ID and the non-existent thread UUID.
 * 4. Verify that the API returns an error and does not create the post.
 *
 * Proper edge case and error path handling should be validated (e.g., forbidden, not found, or business logic error depending on API behavior).
 */
export async function test_api_discussionBoard_test_create_post_with_nonexistent_thread_returns_error(
  connection: api.IConnection,
) {
  // Step 1: Create a member who will attempt to author the post
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(32),
      display_name: RandomGenerator.name(),
      is_active: true
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(member);

  // Step 2: Generate a random UUID for the thread, guaranteeing nonexistence
  const nonExistentThreadId = typia.random<string & tags.Format<"uuid">>();

  // Step 3: Attempt to create a post with the non-existent thread UUID
  await TestValidator.error("Creating post on non-existent thread should fail")(
    async () =>
      api.functional.discussionBoard.articles.posts.post(connection, {
        body: {
          discussion_board_thread_id: nonExistentThreadId,
          discussion_board_member_id: member.id,
          body: RandomGenerator.paragraph()(),
        } satisfies IDiscussionBoardPost.ICreate,
      })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";

/**
 * Test creating a post on a soft-deleted discussion thread should fail with an error.
 *
 * This test ensures that the API correctly enforces business rules regarding posting in deleted threads:
 * - Threads with a soft delete ("deleted_at" set) must not allow new posts to be created.
 *
 * Workflow:
 * 1. Register a new forum member (author)
 * 2. Create a new category
 * 3. Create a new thread in that category by the member
 * 4. Soft-delete the thread
 * 5. Attempt to create a post (reply) in the deleted thread — should fail
 */
export async function test_api_discussionBoard_test_create_post_on_soft_deleted_thread_returns_error(
  connection: api.IConnection,
) {
  // 1. Register a new member (author)
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      profile_image_url: null,
      is_active: true,
    } satisfies IdiscussionBoardMembers.ICreate,
  });
  typia.assert(member);

  // 2. Create a new category
  const category = await api.functional.discussionBoard.categories.categories.post(connection, {
    body: {
      name: RandomGenerator.paragraph()(3),
      description: RandomGenerator.paragraph()(),
    } satisfies IDiscussionBoardCategory.ICreate,
  });
  typia.assert(category);

  // 3. Create a new thread in the new category
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, {
    body: {
      discussion_board_category_id: category.id,
      title: RandomGenerator.paragraph()(2),
      body: RandomGenerator.content()()(),
      is_pinned: false,
      is_closed: false,
    } satisfies IDiscussionBoardThread.ICreate,
  });
  typia.assert(thread);

  // 4. Soft-delete the thread
  const deleteResult = await api.functional.discussionBoard.articles.threads.eraseById(connection, {
    id: thread.id,
  });
  typia.assert(deleteResult);
  TestValidator.predicate("deletion success")(deleteResult.success);
  TestValidator.predicate("thread.deleted_at is set")(!!deleteResult.thread.deleted_at);

  // 5. Attempt to create a post in the soft-deleted thread — must fail
  await TestValidator.error("cannot post in deleted thread")(async () => {
    await api.functional.discussionBoard.articles.posts.post(connection, {
      body: {
        discussion_board_thread_id: thread.id,
        discussion_board_member_id: member.id,
        body: RandomGenerator.content()()(),
      } satisfies IDiscussionBoardPost.ICreate,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";

/**
 * Validate that attempting to create a discussion board post as an inactive member is denied by the API.
 *
 * Business context: Users who have been deactivated (is_active=false) or banned should not be able to create forum posts per requirements.
 * This test ensures strict business rule enforcement on member states.
 *
 * Test steps:
 * 1. Create a new discussion board member (active by default at creation).
 * 2. Update the member's profile to set `is_active` to false, simulating a deactivated user.
 * 3. Attempt to create a new post using this inactive member's UUID as the author.
 * 4. Expect and assert that the post creation is forbidden (error occurs).
 *
 * This verifies that post-creation logic checks the member's active status and enforces authorization at the API level.
 */
export async function test_api_discussionBoard_test_create_post_with_inactive_member_returns_error(
  connection: api.IConnection,
) {
  // 1. Create a member (active at creation)
  const memberInput: IdiscussionBoardMembers.ICreate = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(32),
    display_name: RandomGenerator.name(),
    is_active: true,
    profile_image_url: null,
  };
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: memberInput,
  });
  typia.assert(member);

  // 2. Deactivate the member (is_active = false)
  const updatedMember = await api.functional.discussionBoard.actors.members.putById(connection, {
    id: member.id,
    body: { is_active: false },
  });
  typia.assert(updatedMember);
  TestValidator.equals("member should now be inactive")(updatedMember.is_active)(false);

  // 3. Attempt to create a post with inactive member
  const postInput: IDiscussionBoardPost.ICreate = {
    discussion_board_thread_id: typia.random<string & tags.Format<"uuid">>(),
    discussion_board_member_id: member.id,
    body: RandomGenerator.paragraph()(),
  };
  await TestValidator.error("should not allow post creation from inactive member")(
    () => api.functional.discussionBoard.articles.posts.post(connection, { body: postInput })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IPageIDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPost";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";

/**
 * 스레드 ID별 게시글 목록 페이징 조회 기능 검증.
 *
 * 본 테스트는 토론 게시판에서 특정 스레드에 게시된 게시글들에 대해, 페이징 처리를 적용한 목록 API가 정확히 동작하는지 확인합니다.
 * 회원, 카테고리, 스레드 및 복수개의 게시글 생성 과정 이후,
 * PATCH /discussionBoard/articles/posts 엔드포인트에 thread ID, 페이지 번호와 개수 제한(limit) 조건을 넣어 요청하고,
 * 반환된 게시글 목록과 페이징 메타정보가 기대값과 일치하는지 상세 검증합니다.
 *
 * 절차:
 * 1. 새로운 회원을 생성한다.
 * 2. 카테고리를 생성한다.
 * 3. 해당 카테고리와 회원으로 새로운 스레드를 등록한다.
 * 4. 동일 스레드에 7개의 게시글을 추가 생성한다.
 * 5. PATCH /discussionBoard/articles/posts 를 통해, thread_id와 limit=5, page=1 조건으로 1페이지만큼 목록을 조회하여 검증한다.
 *    - 5개의 게시글, 올바른 페이징 메타(현재 page, limit, 총 레코드 수 등)가 반환되어야 한다.
 *    - 스레드 ID 및 게시 순서 일치 여부를 체크한다.
 * 6. 같은 방식으로 page=2로 2페이지 조회 결과(2개 게시글, 페이징 메타 반영)도 검증한다.
 */
export async function test_api_discussionBoard_test_list_posts_by_thread_id_with_pagination(
  connection: api.IConnection,
) {
  // 1. 회원 생성
  const memberInput: IdiscussionBoardMembers.ICreate = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(16),
    display_name: RandomGenerator.name(),
    profile_image_url: null,
    is_active: true,
  };
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: memberInput,
  });
  typia.assert(member);

  // 2. 카테고리 생성
  const category = await api.functional.discussionBoard.categories.categories.post(connection, {
    body: {
      name: RandomGenerator.alphaNumeric(10),
      description: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(category);

  // 3. 스레드 생성 (회원/카테고리 지정)
  const threadInput: IDiscussionBoardThread.ICreate = {
    discussion_board_category_id: category.id,
    title: RandomGenerator.paragraph()(),
    body: RandomGenerator.content()()(),
    is_pinned: false,
    is_closed: false,
  };
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, {
    body: threadInput,
  });
  typia.assert(thread);

  // 4. 동일 스레드에 7개 게시글 생성
  const postInputs = ArrayUtil.repeat(7)(i => ({
    discussion_board_thread_id: thread.id,
    discussion_board_member_id: member.id,
    body: RandomGenerator.paragraph()(),
  } satisfies IDiscussionBoardPost.ICreate));
  const createdPosts = await ArrayUtil.asyncMap(postInputs)(async input => {
    const post = await api.functional.discussionBoard.articles.posts.post(connection, { body: input });
    typia.assert(post);
    return post;
  });
  // 생성 시각 기준(오름차순)으로 정렬
  createdPosts.sort((a, b) => new Date(a.created_at).getTime() - new Date(b.created_at).getTime());

  // 5. page=1/limit=5로 목록 조회 & 검증
  const page1Response = await api.functional.discussionBoard.articles.posts.patch(connection, {
    body: {
      discussion_board_thread_id: thread.id,
      page: 1,
      limit: 5,
    } satisfies IDiscussionBoardPost.IListRequest,
  });
  typia.assert(page1Response);
  TestValidator.equals("페이지1 게시글 개수")(page1Response.data.length)(5);
  TestValidator.equals("페이지1 현재 page")(page1Response.pagination.current)(1);
  TestValidator.equals("페이지1 limit")(page1Response.pagination.limit)(5);
  TestValidator.equals("페이지1 총 레코드 수")(page1Response.pagination.records)(7);
  TestValidator.equals("페이지1 총 페이지 수")(page1Response.pagination.pages)(2);
  // 게시글 ID/스레드 일치 확인
  for (let i = 0; i < 5; ++i) {
    TestValidator.equals(`p1 게시글${i} id`)(page1Response.data[i].id)(createdPosts[i].id);
    TestValidator.equals(`p1 게시글${i} thread_id`)(page1Response.data[i].discussion_board_thread_id)(thread.id);
  }

  // 6. page=2/limit=5로 2페이지 조회 & 검증
  const page2Response = await api.functional.discussionBoard.articles.posts.patch(connection, {
    body: {
      discussion_board_thread_id: thread.id,
      page: 2,
      limit: 5,
    },
  });
  typia.assert(page2Response);
  TestValidator.equals("페이지2 게시글 개수")(page2Response.data.length)(2);
  TestValidator.equals("페이지2 현재 page")(page2Response.pagination.current)(2);
  TestValidator.equals("페이지2 limit")(page2Response.pagination.limit)(5);
  TestValidator.equals("페이지2 총 레코드 수")(page2Response.pagination.records)(7);
  TestValidator.equals("페이지2 총 페이지 수")(page2Response.pagination.pages)(2);
  for (let i = 0; i < 2; ++i) {
    TestValidator.equals(`p2 게시글${i} id`)(page2Response.data[i].id)(createdPosts[5 + i].id);
    TestValidator.equals(`p2 게시글${i} thread_id`)(page2Response.data[i].discussion_board_thread_id)(thread.id);
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IPageIDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPost";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";

/**
 * Test filtering discussion board posts by a single member ID across multiple threads.
 *
 * This scenario verifies that the posts listing endpoint can correctly filter by the author's member ID even when posts are spread across different threads.
 *
 * Steps:
 *   1. Create a member who will be authoring posts.
 *   2. Create several categories (one per thread).
 *   3. For each category, create a separate discussion thread authored by the member.
 *   4. In each thread, create one or more posts by the same member.
 *   5. List all posts using the posts PATCH endpoint, filtering by the member's id.
 *   6. Paginate if necessary.
 *   7. Assert:
 *     - Every returned post is authored by the target member
 *     - All created posts are found in the paginated results
 */
export async function test_api_discussionBoard_test_list_posts_by_member_id_with_multiple_threads(
  connection: api.IConnection,
) {
  // 1. Create a member (author)
  const memberEmail: string = typia.random<string & tags.Format<"email">>();
  const memberUsername: string = RandomGenerator.alphaNumeric(10);
  const memberPassword: string = RandomGenerator.alphaNumeric(16);
  const memberDisplayName: string = RandomGenerator.name();

  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: memberUsername,
      email: memberEmail,
      hashed_password: memberPassword,
      display_name: memberDisplayName,
      is_active: true,
      profile_image_url: null,
    },
  });
  typia.assert(member);

  // 2. Create multiple categories and threads
  const THREAD_COUNT = 3;
  const POSTS_PER_THREAD = 2;
  const categories = await Promise.all(
    ArrayUtil.repeat(THREAD_COUNT)((index: number) =>
      api.functional.discussionBoard.categories.categories.post(connection, {
        body: {
          name: `TestCat_${RandomGenerator.alphaNumeric(6)}`,
          description: `Test description ${index}`,
        },
      }).then((cat) => {
        typia.assert(cat);
        return cat;
      })
    ),
  );

  const threads = await Promise.all(
    categories.map((category, idx) =>
      api.functional.discussionBoard.articles.threads.post(connection, {
        body: {
          discussion_board_category_id: category.id,
          title: `Test thread ${idx}`,
          body: `Thread body ${idx}`,
          is_pinned: false,
          is_closed: false,
        },
      }).then((thread) => {
        typia.assert(thread);
        return thread;
      })
    )
  );

  // 3. Create posts by the member in each thread
  const createdPostIds: Array<string> = [];
  for (const thread of threads) {
    for (let i = 0; i < POSTS_PER_THREAD; ++i) {
      const post = await api.functional.discussionBoard.articles.posts.post(connection, {
        body: {
          discussion_board_thread_id: thread.id,
          discussion_board_member_id: member.id,
          body: `Post body for thread ${thread.title}, post #${i}`,
        },
      });
      typia.assert(post);
      createdPostIds.push(post.id);
    }
  }

  // 4. List posts filtering by discussion_board_member_id
  let allRetrievedPostIds: Array<string> = [];
  let page = 1;
  const limit = 2; // Small limit to force pagination
  let totalPages = 1;
  do {
    const result = await api.functional.discussionBoard.articles.posts.patch(connection, {
      body: {
        page: page,
        limit: limit,
        discussion_board_member_id: member.id,
      },
    });
    typia.assert(result);
    TestValidator.predicate("all returned posts belong to the member")(
      result.data.every((p) => p.discussion_board_member_id === member.id),
    );
    allRetrievedPostIds.push(...result.data.map((p) => p.id));

    if (page === 1) totalPages = result.pagination.pages;
    page += 1;
  } while (page <= totalPages);

  // 5. Assert that all created post ids are found among the result
  for (const id of createdPostIds) {
    TestValidator.predicate(`created post with id ${id} was found in paginated results?`)(
      allRetrievedPostIds.includes(id),
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IPageIDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPost";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";

/**
 * Validate that the list posts endpoint excludes soft-deleted posts.
 *
 * This test simulates the process of member and content creation, post deletion,
 * and ensures retrieval does NOT include posts marked deleted (via deleted_at).
 *
 * Steps:
 * 1. Create a new member account to act as the author
 * 2. Create a new discussion board category
 * 3. Create a new thread in that category with the created member
 * 4. Create several (at least 3) posts in that thread, all by the member
 * 5. Soft-delete one post (randomly pick a post)
 * 6. List all posts in the thread and verify the deleted post does not appear
 * 7. Directly assert that posts with deleted_at are missing from result
 */
export async function test_api_discussionBoard_test_list_posts_filters_exclude_soft_deleted_posts(
  connection: api.IConnection,
) {
  // 1. Create a new member account to act as the author
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      is_active: true,
      profile_image_url: null,
    },
  });
  typia.assert(member);

  // 2. Create a new discussion board category
  const category = await api.functional.discussionBoard.categories.categories.post(connection, {
    body: {
      name: RandomGenerator.alphabets(10),
      description: RandomGenerator.paragraph()(1),
    },
  });
  typia.assert(category);

  // 3. Create a new thread in that category with the created member
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, {
    body: {
      discussion_board_category_id: category.id,
      title: RandomGenerator.alphabets(12),
      body: RandomGenerator.content()()(),
      is_pinned: false,
      is_closed: false,
    },
  });
  typia.assert(thread);

  // 4. Create several (at least 3) posts in that thread, all by the member
  const posts = await ArrayUtil.asyncRepeat(3)(async () => {
    const post = await api.functional.discussionBoard.articles.posts.post(connection, {
      body: {
        discussion_board_thread_id: thread.id,
        discussion_board_member_id: member.id,
        body: RandomGenerator.content()()(),
      },
    });
    typia.assert(post);
    return post;
  });

  // 5. Soft-delete one post (randomly pick a post)
  const deletedPost = RandomGenerator.pick(posts);
  const eraseResult = await api.functional.discussionBoard.articles.posts.eraseById(connection, {
    id: deletedPost.id,
  });
  typia.assert(eraseResult);
  TestValidator.predicate("erase should succeed")(eraseResult.success);

  // 6. List all posts in the thread and verify the deleted post does not appear
  const listResult = await api.functional.discussionBoard.articles.posts.patch(connection, {
    body: { discussion_board_thread_id: thread.id },
  });
  typia.assert(listResult);

  // 7. Directly assert that posts with deleted_at are missing from result, and the deleted post is absent
  const returnedIds = listResult.data.map((p) => p.id);
  TestValidator.predicate("soft deleted post not listed")(!returnedIds.includes(deletedPost.id));
  posts.filter((post) => post.id !== deletedPost.id).forEach((post) =>
    TestValidator.predicate("undeleted post present")(returnedIds.includes(post.id)),
  );
  listResult.data.forEach((post) =>
    TestValidator.equals("no deleted_at")(post.deleted_at)(null),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
