import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";

/**
 * Validate that only moderators can access soft-deleted discussion board posts, while regular members cannot.
 *
 * Business context: A soft-deleted post should not be visible to non-moderator members for both privacy and moderation audit reasons. However, moderators must retain the ability to view and possibly restore or investigate such posts. This test ensures that after a post is soft-deleted, it is only retrievable by an authorized moderator.
 *
 * Test Steps:
 * 1. Register a new member (who will later be a moderator)
 * 2. Assign moderator role to the new member
 * 3. Create a discussion category/thread context
 * 4. Create a new thread as the registered member
 * 5. Create a post in the new thread as the same member
 * 6. Soft-delete the post
 * 7. As a regular member (not moderator), attempt to fetch the soft-deleted post and assert access denied (NotFound or Forbidden)
 * 8. As a moderator, fetch the soft-deleted post and assert full post detail is returned including deleted_at
 */
export async function test_api_discussionBoard_test_get_soft_deleted_post_visible_only_to_moderator(
  connection: api.IConnection,
) {
  // 1. Register a new member (who will later be moderator)
  const memberReq: IdiscussionBoardMembers.ICreate = {
    username: RandomGenerator.alphabets(12),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(32),
    display_name: RandomGenerator.name(),
    profile_image_url: null,
    is_active: true,
  };
  const member = await api.functional.discussionBoard.actors.members.post(connection, { body: memberReq });
  typia.assert(member);

  // 2. Assign moderator role to this member
  const modReq: IdiscussionBoardModerators.ICreate = {
    member_id: member.id,
    assigned_at: new Date().toISOString(),
  };
  const moderator = await api.functional.discussionBoard.actors.moderators.post(connection, { body: modReq });
  typia.assert(moderator);

  // 3. Create a new discussion category
  const catReq: IDiscussionBoardCategory.ICreate = {
    name: RandomGenerator.alphabets(10),
    description: RandomGenerator.paragraph()(),
  };
  const category = await api.functional.discussionBoard.categories.categories.post(connection, { body: catReq });
  typia.assert(category);

  // 4. Create a thread in the new category as this member
  const threadReq: IDiscussionBoardThread.ICreate = {
    discussion_board_category_id: category.id,
    title: RandomGenerator.paragraph()(),
    body: RandomGenerator.content()()(),
    is_pinned: false,
    is_closed: false,
  };
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, { body: threadReq });
  typia.assert(thread);

  // 5. Create a post in the new thread
  const postReq: IDiscussionBoardPost.ICreate = {
    discussion_board_thread_id: thread.id,
    discussion_board_member_id: member.id,
    body: RandomGenerator.content()()(),
  };
  const post = await api.functional.discussionBoard.articles.posts.post(connection, { body: postReq });
  typia.assert(post);

  // 6. Soft-delete the post
  const delResult = await api.functional.discussionBoard.articles.posts.eraseById(connection, { id: post.id });
  typia.assert(delResult);
  TestValidator.predicate("soft delete success")(delResult.success === true);
  TestValidator.equals("deleted_at set on post")(typeof delResult.post.deleted_at === "string")(true);

  // 7. Attempt to fetch soft-deleted post as a regular member (should error)
  await TestValidator.error("Regular member cannot fetch soft-deleted post")(
    async () => {
      await api.functional.discussionBoard.articles.posts.getById(connection, { id: post.id });
    },
  );

  // 8. As a moderator, fetch the soft-deleted post (should succeed)
  // In real auth, connection context would be refreshed; here we assume moderator context is set already
  const softDeleted = await api.functional.discussionBoard.articles.posts.getById(connection, { id: post.id });
  typia.assert(softDeleted);
  TestValidator.equals("soft-deleted post id")(softDeleted.id)(post.id);
  TestValidator.equals("soft-deleted post has deleted_at")(typeof softDeleted.deleted_at === "string")(true);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";

/**
 * Test that the original author can successfully update their own comment's body.
 *
 * Business context:
 * Members may want to edit typos or enhance their comments on articles/posts.
 * Only the comment's author (not others) is allowed to update the body.
 *
 * Process steps:
 * 1. Register a new member account.
 * 2. Create a thread under a category as this member.
 * 3. Create a post within the thread (by the same member).
 * 4. Add a comment to the post as the member.
 * 5. Attempt to update the comment's body (still as the author).
 * 6. Assert that:
 *    - Comment body's value has changed as intended.
 *    - is_edited is now true.
 *    - updated_at reflects a more recent time than previous updated_at.
 *    - All other fields are unaffected.
 *
 * This ensures only allowed fields are changed and the comment is marked as edited.
 */
export async function test_api_discussionBoard_test_update_comment_body_successfully_by_author(
  connection: api.IConnection,
) {
  // 1. Register a new member.
  const memberInput: IdiscussionBoardMembers.ICreate = {
    username: RandomGenerator.alphaNumeric(10),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(32),
    display_name: RandomGenerator.name(),
    is_active: true,
    profile_image_url: null,
  };
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: memberInput,
  });
  typia.assert(member);

  // 2. Create a thread as this member (using a random category ID).
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const threadInput: IDiscussionBoardThread.ICreate = {
    discussion_board_category_id: categoryId,
    title: RandomGenerator.paragraph()(1),
    body: RandomGenerator.content()(1)(2),
    is_pinned: false,
    is_closed: false,
  };
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, {
    body: threadInput,
  });
  typia.assert(thread);

  // 3. Create a post within the thread.
  const postInput: IDiscussionBoardPost.ICreate = {
    discussion_board_thread_id: thread.id,
    discussion_board_member_id: member.id,
    body: RandomGenerator.content()(1)(3),
  };
  const post = await api.functional.discussionBoard.articles.posts.post(connection, {
    body: postInput,
  });
  typia.assert(post);

  // 4. Add a comment to the post as the member.
  const commentInput: IDiscussionBoardComment.ICreate = {
    discussion_board_post_id: post.id,
    discussion_board_member_id: member.id,
    body: RandomGenerator.paragraph()(2),
  };
  const comment = await api.functional.discussionBoard.articles.comments.post(connection, {
    body: commentInput,
  });
  typia.assert(comment);

  // 5. Update the comment's body (by the same author).
  const newBody = RandomGenerator.paragraph()(3);
  // Wait a moment to ensure updated_at can differ
  await new Promise((resolve) => setTimeout(resolve, 1000));
  const updatedComment = await api.functional.discussionBoard.articles.comments.putById(connection, {
    id: comment.id,
    body: { body: newBody },
  });
  typia.assert(updatedComment);

  // 6. Assertions
  TestValidator.equals("body was updated")(updatedComment.body)(newBody);
  TestValidator.equals("is_edited is true")(updatedComment.is_edited)(true);
  TestValidator.predicate("updated_at advanced")(Date.parse(updatedComment.updated_at) > Date.parse(comment.updated_at));
  // All other fields should be the same (except updated fields)
  TestValidator.equals("id unchanged")(updatedComment.id)(comment.id);
  TestValidator.equals("discussion_board_post_id unchanged")(updatedComment.discussion_board_post_id)(comment.discussion_board_post_id);
  TestValidator.equals("parent_id unchanged")(updatedComment.parent_id ?? null)(comment.parent_id ?? null);
  TestValidator.equals("discussion_board_member_id unchanged")(updatedComment.discussion_board_member_id)(comment.discussion_board_member_id);
  TestValidator.equals("created_at unchanged")(updatedComment.created_at)(comment.created_at);
  TestValidator.equals("deleted_at unchanged")(updatedComment.deleted_at ?? null)(comment.deleted_at ?? null);
}

