import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";

/**
 * 비작성자(비 소유 멤버)가 댓글 soft delete를 시도할 때 거부되는지 검증합니다.
 *
 * - 시나리오: 두 명의 멤버 회원가입 → 첫 번째 멤버(owner)로 스레드/게시물/댓글 작성 →
 *   두 번째 멤버(non-owner)가 해당 댓글에 soft delete(DELETE) 시도 →
 *   응답의 result가 "forbidden"인지, deleted_at 시각이 원래 null(혹은 변경 없음)인지 확인
 *
 * [테스트 프로세스]
 * 1. owner 멤버 회원가입
 * 2. non-owner 멤버 회원가입
 * 3. owner 계정으로 스레드 생성
 * 4. owner 계정으로 게시물 생성
 * 5. owner 계정으로 댓글 생성
 * 6. (권한전환 로직 없음: member2 ID만으로 대리)
 * 7. non-owner가 soft delete 시도
 * 8. 응답의 result == "forbidden", deleted_at 변동 없음 검증
 */
export async function test_api_discussionBoard_test_soft_delete_comment_by_non_author_forbidden(
  connection: api.IConnection,
) {
  // 1. owner 멤버 회원가입
  const ownerSignup = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(16),
    display_name: RandomGenerator.name(),
    is_active: true,
    profile_image_url: null,
  } satisfies IdiscussionBoardMembers.ICreate;
  const member1 = await api.functional.discussionBoard.actors.members.post(connection, { body: ownerSignup });
  typia.assert(member1);

  // 2. non-owner 멤버 회원가입
  const nonOwnerSignup = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(16),
    display_name: RandomGenerator.name(),
    is_active: true,
    profile_image_url: null,
  } satisfies IdiscussionBoardMembers.ICreate;
  const member2 = await api.functional.discussionBoard.actors.members.post(connection, { body: nonOwnerSignup });
  typia.assert(member2);

  // 3. owner로 스레드 생성
  const threadInput = {
    discussion_board_category_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.paragraph()(),
    body: RandomGenerator.paragraph()(),
    is_pinned: false,
    is_closed: false,
  } satisfies IDiscussionBoardThread.ICreate;
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, { body: threadInput });
  typia.assert(thread);

  // 4. owner로 post 생성
  const postInput = {
    discussion_board_thread_id: thread.id,
    discussion_board_member_id: member1.id,
    body: RandomGenerator.content()()(),
  } satisfies IDiscussionBoardPost.ICreate;
  const post = await api.functional.discussionBoard.articles.posts.post(connection, { body: postInput });
  typia.assert(post);

  // 5. owner로 댓글 생성
  const commentInput = {
    discussion_board_post_id: post.id,
    discussion_board_member_id: member1.id,
    body: RandomGenerator.paragraph()(),
  } satisfies IDiscussionBoardComment.ICreate;
  const comment = await api.functional.discussionBoard.articles.comments.post(connection, { body: commentInput });
  typia.assert(comment);

  // 6. (권한 전환 구현 불가: member2 ID 대리)
  // 7. member2(비작성자)가 soft delete 시도
  const result = await api.functional.discussionBoard.articles.comments.eraseById(connection, { id: comment.id });
  typia.assert(result);
  TestValidator.equals("권한 거부 result")(result.result)("forbidden");
  // deleted_at은 forbidden일 때 기존 값(일반적으로 null) 유지
  TestValidator.equals("삭제 시각 없음 유지")(result.deleted_at)(comment.deleted_at ?? null);
}

