 *
 * Step-by-step:
 * 1. Register a new member with unique username and email.
 * 2. Issue a notification to this member (creates a notification event).
 * 3. As the recipient, update this notification—mark as read, update content_preview and delivered_at.
 * 4. Confirm the changes are reflected in the returned record.
 * 5. (Edge) Attempt to update a soft-deleted notification (should fail—but not implemented, as no delete endpoint in SDK).
 */
export async function test_api_discussionBoard_notifications_notifications_putById(
  connection: api.IConnection,
) {
  // 1. Register a unique discussion board member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberUsername = RandomGenerator.alphaNumeric(8);
  const member: IdiscussionBoardMembers = await api.functional.discussionBoard.actors.members.post(
    connection,
    {
      body: {
        username: memberUsername,
        email: memberEmail,
        hashed_password: RandomGenerator.alphaNumeric(16),
        display_name: RandomGenerator.name(),
        profile_image_url: null,
        is_active: true,
      } satisfies IdiscussionBoardMembers.ICreate,
    },
  );
  typia.assert(member);

  // 2. Issue a notification to this member
  const now = new Date().toISOString();
  const notification: IDiscussionBoardNotification = await api.functional.discussionBoard.notifications.notifications.post(
    connection,
    {
      body: {
        recipient_member_id: member.id,
        trigger_actor_id: null, // system triggered
        type: "reply", // generic notification type
        content_preview: "Initial content preview for test.",
        url: "https://board.example.com/thread/12345",
        read: false,
        delivered_at: null,
        created_at: now,
      } satisfies IDiscussionBoardNotification.ICreate,
    },
  );
  typia.assert(notification);

  // 3. Update: Mark as read, update preview and delivery timestamp
  const deliveredAt = new Date(Date.now() + 60 * 1000).toISOString(); // 1 minute later
  const updatedPreview = "Updated content preview after marking as read.";
  const updated: IDiscussionBoardNotification = await api.functional.discussionBoard.notifications.notifications.putById(
    connection,
    {
      id: notification.id,
      body: {
        read: true,
        content_preview: updatedPreview,
        delivered_at: deliveredAt,
      } satisfies IDiscussionBoardNotification.IUpdate,
    },
  );
  typia.assert(updated);

  // 4. Validate that the changes reflect on the updated notification
  TestValidator.equals("notification read state")(updated.read)(true);
  TestValidator.equals("notification content_preview")(updated.content_preview)(updatedPreview);
  TestValidator.equals("notification delivered_at")(updated.delivered_at)(deliveredAt);
  TestValidator.equals("notification id unchanged")(updated.id)(notification.id);
  TestValidator.equals("notification recipient")(updated.recipient_member_id)(member.id);
  TestValidator.equals("soft-deleted")(updated.deleted_at)(null);
}

