 * 
 * 1. 멤버 계정 신규 등록
 * 2. 서로 다른 target_type, target_id 조합으로 다수의 구독 생성
 * 3. member_id 단독 필터로 전체 구독 리스트 조회 및 멤버 일치성 검증
 * 4. member_id + target_type 복합 필터로 조회 결과의 type, member 값 모두 정확성 검증
 * 5. 반환 pagination 정보 및 각 항목 typia.assert로 스키마 일치 확인
 */
export async function test_api_discussionBoard_notifications_subscriptions_test_list_notification_subscriptions_with_valid_filters(
  connection: api.IConnection
) {
  // 1. 멤버 계정 생성
  const memberCreate = {
    username: RandomGenerator.alphabets(8),
