    TestValidator.equals("멤버 일치")(item.member_id)(member.id);
    TestValidator.equals("target_type 일치")(item.target_type)(targetTypeToCheck);
  }

  // 5. pagination 및 구조 검증
  TestValidator.predicate("pagination current 1 이상")(pageByType.pagination.current >= 1);
  TestValidator.predicate("pagination limit 1 이상")(pageByType.pagination.limit >= 1);
  TestValidator.predicate("pagination records 1 이상")(pageByType.pagination.records >= 1);
}

