 *
 * 이 테스트는 다음과 같은 실제 비즈니스 흐름을 검증합니다:
 * - 등록 회원(투표자) 생성
 * - 투표 유형(예: upvote) 생성
 * - 회원이 아직 해당 스레드에 이 투표 유형으로 투표하지 않은 상태에서 타겟 스레드 생성
 * - 투표 API에 모든 필수 필드를 제공하여 투표 생성 요청
 *
 * 검증 포인트:
 * 1. 생성된 투표 레코드의 voter_id/vote_type_id/thread_id 연관 관계가 정확한가?
 * 2. 스키마 상 고유 제약조건(동일 투표자-동일 스레드-동일 투표타입 중복 불가)이 실제 데이터에 잘 적용되는가?
 *
 * [세부 테스트 단계]
 * 1. 토론게시판 회원 등록(중복 없는 랜덤 정보)
 * 2. 투표 타입(upvote 등) 등록(고유한 code)
 * 3. 해당 회원을 이용하여 새로운 스레드 등록
 * 4. 등록한 멤버가, 특정 투표유형으로, 방금 생성한 스레드에 투표 요청
 * 5. 반환된 투표 레코드의 voter_id/vote_type_id/thread_id 값, 그리고 반환 데이터 타입을 모두 명확히 검증
 */
export async function test_api_discussionBoard_test_create_vote_thread_success(
  connection: api.IConnection,
) {
  // 1. 토론게시판 회원(투표자) 생성
  const username = RandomGenerator.alphaNumeric(8);
  const email = `${RandomGenerator.alphaNumeric(8)}@example.com`;
  const displayName = RandomGenerator.name();
  const hashedPassword = RandomGenerator.alphaNumeric(32); // 실제 환경은 해시값, 여기선 임의 문자열
  const member = await api.functional.discussionBoard.actors.members.post(connection, {
    body: {
      username,
      email,
      hashed_password: hashedPassword,
      display_name: displayName,
      is_active: true,
      profile_image_url: null,
    },
  });
  typia.assert(member);

  // 2. 투표 타입(upvote) 생성
  const voteTypeCode = `${RandomGenerator.alphaNumeric(6)}-test`;
  const voteType = await api.functional.discussionBoard.votes.voteTypes.post(connection, {
    body: {
      code: voteTypeCode,
      name: `테스트업보트-${voteTypeCode}`,
      description: "테스트용 업보트 타입입니다.",
    },
  });
  typia.assert(voteType);

  // 3. 투표 대상 스레드 생성(카테고리도 랜덤 UUID)
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, {
    body: {
      discussion_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
      is_pinned: false,
      is_closed: false,
    },
  });
  typia.assert(thread);

  // 4. 투표 생성 (아직 중복 투표 없음)
  const vote = await api.functional.discussionBoard.votes.votes.post(connection, {
    body: {
      voter_id: member.id,
      vote_type_id: voteType.id,
      thread_id: thread.id,
      post_id: null,
      comment_id: null,
    },
  });
  typia.assert(vote);
  // 5. 반환값 상세 검증
  TestValidator.equals("voter_id 확인")(vote.voter_id)(member.id);
  TestValidator.equals("vote_type_id 확인")(vote.vote_type_id)(voteType.id);
  TestValidator.equals("thread_id 확인")(vote.thread_id)(thread.id);
  TestValidator.equals("post_id는 null이어야 함")(vote.post_id)(null);
  TestValidator.equals("comment_id는 null이어야 함")(vote.comment_id)(null);
}

