    body: {
      code: `upvote_${RandomGenerator.alphaNumeric(6)}`,
      name: "Upvote",
      description: "Upvote for comment",
    },
  });
  typia.assert(voteType);

  // 3. 스레드 카테고리 UUID 임의 생성 및 스레드 생성
  const threadCategoryId = typia.random<string & tags.Format<"uuid">>();
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, {
    body: {
      discussion_board_category_id: threadCategoryId,
