/**
 * Validate strict schema enforcement when creating a vote.
 *
 * This test ensures that the vote creation endpoint rejects or ignores forbidden (extra) fields and enforces schema validation strictly. It also verifies that required relationships (such as voter, vote type, and target entity) are properly validated.
 *
 * Steps:
 * 1. Create a member voter using the appropriate endpoint.
 * 2. Create a valid vote type using the vote type creation endpoint.
 * 3. Create a thread to serve as target for the vote.
 * 4. Successfully create a valid vote as a baseline check.
 * 5. Attempt to create a vote with forbidden extra fields and confirm that the API rejects the request (error expected).
 * 6. Attempt to create a vote missing required relationships (all of thread_id, post_id, comment_id omitted) and confirm that the API validation fails.
 */
export async function test_api_discussionBoard_test_create_vote_forbidden_fields_ignored(
  connection: api.IConnection,
) {
  // 1. Create a member voter
  const memberReq: IdiscussionBoardMembers.ICreate = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(16),
    display_name: RandomGenerator.name(),
    is_active: true,
  };
  const member = await api.functional.discussionBoard.actors.members.post(connection, { body: memberReq });
  typia.assert(member);

  // 2. Create a vote type
  const voteTypeReq: discussion_board_vote_types.ICreate = {
    code: RandomGenerator.alphabets(7).toLowerCase(),
    name: "Test Upvote",
    description: "For test case.",
  };
  const voteType = await api.functional.discussionBoard.votes.voteTypes.post(connection, { body: voteTypeReq });
  typia.assert(voteType);

  // 3. Create a thread
  const threadReq: IDiscussionBoardThread.ICreate = {
    discussion_board_category_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.paragraph()(),
    body: RandomGenerator.content()()(),
    is_pinned: false,
    is_closed: false,
  };
  const thread = await api.functional.discussionBoard.articles.threads.post(connection, { body: threadReq });
  typia.assert(thread);

  // 4. Baseline — create a valid vote (should succeed)
  const properVoteReq: discussion_board_votes.ICreate = {
    voter_id: member.id,
    vote_type_id: voteType.id,
    thread_id: thread.id,
  };
  const properVote = await api.functional.discussionBoard.votes.votes.post(connection, { body: properVoteReq });
  typia.assert(properVote);
  TestValidator.equals("voter_id")(properVote.voter_id)(member.id);
  TestValidator.equals("vote_type_id")(properVote.vote_type_id)(voteType.id);
  TestValidator.equals("thread_id")(properVote.thread_id)(thread.id);

  // 5. Attempt to create a vote with an extra forbidden field. Should fail
  TestValidator.error("Creating vote with forbidden extra fields should fail")(async () => {
    const invalidVoteReq = {
      voter_id: member.id,
      vote_type_id: voteType.id,
      thread_id: thread.id,
      unexpected_field: "intruder!", // forbidden field
    } as any;
    await api.functional.discussionBoard.votes.votes.post(connection, { body: invalidVoteReq });
  });

  // 6. Attempt to create a vote with all relationships omitted (thread_id, post_id, comment_id missing). Should fail
  TestValidator.error("Schema should require at least one target id (thread/post/comment)")(async () => {
    const invalidVoteReq = {
      voter_id: member.id,
      vote_type_id: voteType.id,
    } satisfies discussion_board_votes.ICreate;
    await api.functional.discussionBoard.votes.votes.post(connection, { body: invalidVoteReq });
  });
}

