import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardChannel";
import type { IDiscussionBoardSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSection";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageDiscussionBoardSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionBoardSection";

/**
 * 토론 게시판 섹션(게시판 그룹) 목록 기본 조회 및 페이지네이션 동작을 검증합니다.
 *
 * ▸ 관리자/운영자 시나리오로, 여러 채널(상위 그룹)과 다수 섹션(게시판)을 생성한 후,
 *    별다른 필터 없이(디폴트/최소 입력) 전체 섹션 목록을 페이징 방식으로 조회할 때,
 *    실제 반환 데이터가 (1) 정상 타입, (2) deleted_at 없는 활성 섹션만 반환, (3) 페이지네이션 구조 및 수치가
 *    모두 정확한지 검증합니다.
 *
 * 1. 테스트용 채널을 여러 개 생성한다.
 * 2. 각 채널당 섹션을 여러 개 생성한다.
 * 3. (소프트딜리트 API 미제공 – 삭제 없이 진행) 모든 섹션은 활성 상태로 간주.
 * 4. 아무 필터 없이(discussion_board_section.IRequest 빈 객체) 페치 요청.
 * 5. 반환값의 구조, type, 페이지네이션 챙겨, 활성 섹션만 포함되는지 체크.
 * 6. 본 테스트에서 생성된 섹션들이 응답 데이터에 일부 혹은 전부 포함되는지 체크(전체 일치까지는 미보장)
 */
export async function test_api_discussionBoard_test_list_sections_with_default_pagination_and_no_filters(
  connection: api.IConnection,
) {
  // 1. 여러 채널 생성
  const channels: IDiscussionBoardChannel[] = [];
  for (let i = 0; i < 3; ++i) {
    const channel = await api.functional.discussionBoard.systematic.channels.post(connection, {
      body: {
        code: `test-channel-${RandomGenerator.alphabets(6)}-${i}`,
        name: `테스트 채널 ${i}`,
        description: `자동 테스트용 채널 설명 ${i}`,
      } satisfies IDiscussionBoardChannel.ICreate,
    });
    typia.assert(channel);
    channels.push(channel);
  }

  // 2. 각 채널별로 섹션 여러 개 생성
  const createdSections: IDiscussionBoardSection[] = [];
  for (const channel of channels) {
    for (let j = 0; j < 4; ++j) {
      const section = await api.functional.discussionBoard.systematic.sections.post(connection, {
        body: {
          discussion_board_channel_id: channel.id,
          code: `sect-${RandomGenerator.alphabets(5)}-${j}`,
          name: `테스트 섹션 ${j} (${channel.code})`,
          description: `자동 테스트용 섹션 설명 ${j}`,
        } satisfies IDiscussionBoardSection.ICreate,
      });
      typia.assert(section);
      createdSections.push(section);
    }
  }

  // 3. 소프트 딜리트 지원 API 없음 – 모두 활성 섹션

  // 4. 필터 없는(최소 입력) 섹션 목록 페치
  const pageResult = await api.functional.discussionBoard.systematic.sections.patch(connection, {
    body: {} satisfies IDiscussionBoardSection.IRequest,
  });
  typia.assert(pageResult);

  // 5. 도메인, 구조, 페이지네이션, 활성 데이터만 반환되는지 검증
  TestValidator.equals("pagination 구조(typeof object)")(typeof pageResult.pagination === "object")(true);
  TestValidator.predicate("pagination 필드 존재")(typeof pageResult.pagination.current === "number"
    && typeof pageResult.pagination.limit === "number"
    && typeof pageResult.pagination.records === "number"
    && typeof pageResult.pagination.pages === "number");

  for (const s of pageResult.data) {
    TestValidator.equals("deleted_at 없음 active 섹션만")(s.deleted_at)(null);
  }

  // 6. 본 테스트에서 생성한 섹션들이 일부 이상 포함되는지(전체 일치는 불가)
  const createdIDs = new Set(createdSections.map(sec => sec.id));
  const found = pageResult.data.filter(sec => createdIDs.has(sec.id));
  TestValidator.predicate("생성 섹션 포함 여부, 일부 이상 present")(found.length >= createdSections.length);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardChannel";
import type { IDiscussionBoardSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSection";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageDiscussionBoardSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionBoardSection";

/**
 * 상위 토론 채널 ID와 섹션명 부분일치로 섹션 목록 필터 검색을 검증한다.
 *
 * 이 테스트는:
 * 1. 신규 토론 채널을 생성한 뒤
 * 2. 해당 채널 내에 이름이 서로 다른 여러 섹션(예: '정치', '경제', '정책', '정치사회')을 생성하고
 * 3. '정치'라는 fragment(부분 문자열)에 대해, 채널 ID+이 fragment가 포함된 이름으로 페치(search) API를 호출하여
 * 4. fragment가 포함된 섹션명만 조회결과에 포함되고, 다른 이름의 섹션은 결과에 없는지 검증한다.
 * 페이징 메타-데이터와 실제 데이터 개수/내용도 교차 확인하여, 논리적 정합성을 체크한다.
 */
export async function test_api_discussionBoard_test_search_sections_with_filtering_by_channel_id_and_name(
  connection: api.IConnection,
) {
  // 1. 신규 토론 채널 생성
  const channelInput = {
    code: RandomGenerator.alphaNumeric(8),
    name: RandomGenerator.paragraph()(2),
    description: RandomGenerator.content()()(1),
  } satisfies IDiscussionBoardChannel.ICreate;
  const channel = await api.functional.discussionBoard.systematic.channels.post(connection, { body: channelInput });
  typia.assert(channel);

  // 2. 다양한 이름(정치/경제/정책/정치사회)으로 토론 섹션 등록
  const sectionNames = ["정치", "경제", "정책", "정치사회"];
  const createdSections: IDiscussionBoardSection[] = [];
  for(const name of sectionNames) {
    const sectionInput = {
      discussion_board_channel_id: channel.id,
      code: RandomGenerator.alphaNumeric(8),
      name,
      description: null,
    } satisfies IDiscussionBoardSection.ICreate;
    const section = await api.functional.discussionBoard.systematic.sections.post(connection, { body: sectionInput });
    typia.assert(section);
    createdSections.push(section);
  }

  // 3. fragment(부분 문자열) 및 채널ID 기준으로 섹션 리스트 필터검색
  const nameFragment = "정치";
  const response = await api.functional.discussionBoard.systematic.sections.patch(connection, {
    body: {
      discussion_board_channel_id: channel.id,
      name: nameFragment,
    } satisfies IDiscussionBoardSection.IRequest,
  });
  typia.assert(response);

  // 4. fragment가 포함된 섹션명만 응답 데이터에 존재하는지 교차검증
  const expectedNames = sectionNames.filter((n) => n.includes(nameFragment));
  const actualNames = response.data.map((s) => s.name);
  for (const n of actualNames) {
    if (!n.includes(nameFragment)) {
      throw new Error(`[검색 결과 불일치] fragment '${nameFragment}'가 없는 섹션명: ${n}`);
    }
  }
  TestValidator.equals("section name count matches")(actualNames.length)(expectedNames.length);
  for (const expectedName of expectedNames) {
    if (!actualNames.includes(expectedName)) throw new Error(`[누락된 섹션명] ${expectedName}`);
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardChannel";
import type { IDiscussionBoardSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSection";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageDiscussionBoardSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionBoardSection";

/**
 * Test listing of sections including soft-deleted entries.
 *
 * This test ensures that when requesting a list of sections (with the deleted flag set to true), the API returns both active and soft-deleted sections, each with the correct deleted_at status.
 *
 * Steps:
 * 1. Create a discussion board channel to serve as the container for sections.
 * 2. Create a section within this channel.
 * 3. Soft-delete the created section.
 * 4. List all sections for this channel, specifying 'deleted: true' to include soft-deleted items.
 * 5. Verify that the response includes the soft-deleted section (deleted_at is a string), and that any non-deleted sections have deleted_at == null.
 */
export async function test_api_discussionBoard_systematic_sections_test_list_sections_including_soft_deleted(
  connection: api.IConnection,
) {
  // 1. Create a parent channel for the test
  const channel = await api.functional.discussionBoard.systematic.channels.post(connection, {
    body: {
      code: RandomGenerator.alphaNumeric(12),
      name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.paragraph()(1),
    },
  });
  typia.assert(channel);

  // 2. Create a section within this channel
  const section = await api.functional.discussionBoard.systematic.sections.post(connection, {
    body: {
      discussion_board_channel_id: channel.id,
      code: RandomGenerator.alphaNumeric(12),
      name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.paragraph()(1),
    },
  });
  typia.assert(section);

  // 3. Soft-delete the created section
  const erased = await api.functional.discussionBoard.systematic.sections.eraseById(connection, {
    id: section.id,
  });
  typia.assert(erased);
  TestValidator.predicate("deleted_at must be set after soft-delete!")(typeof erased.deleted_at === "string" && erased.deleted_at.length > 0);

  // 4. List all sections for this channel, including soft-deleted
  const result = await api.functional.discussionBoard.systematic.sections.patch(connection, {
    body: {
      discussion_board_channel_id: channel.id,
      deleted: true,
    },
  });
  typia.assert(result);

  // 5. Check that erased section is returned with deleted_at
  const found = result.data.find((s) => s.id === erased.id);
  TestValidator.predicate("soft-deleted section must be present")(!!found);
  TestValidator.predicate("soft-deleted section must have deleted_at")(!!found && typeof found.deleted_at === "string" && found.deleted_at.length > 0);

  // Also check that other sections, if any, are not marked as deleted
  for (const s of result.data) {
    if (s.id !== erased.id) TestValidator.equals("deleted_at for non-deleted")(s.deleted_at)(null);
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardChannel";
import type { IDiscussionBoardSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSection";

/**
 * section 상세 정보 조회 (id 기반) 성공 케이스를 검증하는 E2E 테스트입니다.
 *
 * [비즈니스 목적 및 맥락]
 * - 토론 게시판의 section 데이터는 반드시 channel(부모)에 속해야 하며,
 *   본 테스트는 section 생성 후 id로 상세 조회할 때 계약/필드 일치, 스키마 준수 여부를 보장합니다.
 *
 * [테스트 절차]
 * 1. discussion_board_channels에 부모 채널을 하나 생성합니다.
 * 2. 해당 채널 id를 FK로 가진 section을 생성합니다.
 * 3. 생성된 section의 id를 이용하여 상세조회(getById) API를 호출합니다.
 * 4. 상세조회 결과가 section 생성 시 입력/응답 값과 스키마 필드별로 정확히 일치하는지 assert합니다.
 * 5. nullable 및 soft-delete(deleted_at)는 생성 직후 null임을 확인하고,
 * 6. 반환 객체에 스키마에 없는 extraneous property가 없는지도 검사합니다.
 *
 * [검증 포인트]
 * - id / discussion_board_channel_id / code / name / description 정확히 일치
 * - created_at, updated_at ISO8601
 * - deleted_at는 null 또는 undefined
 * - 모든 응답 필드는 스키마 선언된 항목만 포함(extraneous 없음)
 */
export async function test_api_discussionBoard_systematic_sections_test_get_section_detail_by_id_success(
  connection: api.IConnection,
) {
  // 1. 부모 채널 생성
  const channelInput: IDiscussionBoardChannel.ICreate = {
    code: RandomGenerator.alphaNumeric(8),
    name: RandomGenerator.alphaNumeric(12),
    description: RandomGenerator.alphaNumeric(20),
  };
  const channel = await api.functional.discussionBoard.systematic.channels.post(connection, { body: channelInput });
  typia.assert(channel);

  // 2. 채널에 연결된 section 생성
  const sectionInput: IDiscussionBoardSection.ICreate = {
    discussion_board_channel_id: channel.id,
    code: RandomGenerator.alphaNumeric(8),
    name: RandomGenerator.alphaNumeric(14),
    description: RandomGenerator.alphaNumeric(20),
  };
  const section = await api.functional.discussionBoard.systematic.sections.post(connection, { body: sectionInput });
  typia.assert(section);

  // 3. section id로 상세 조회
  const detail = await api.functional.discussionBoard.systematic.sections.getById(connection, { id: section.id });
  typia.assert(detail);

  // 4. 필드 일치 및 준수성 검증
  TestValidator.equals("id")(detail.id)(section.id);
  TestValidator.equals("discussion_board_channel_id")(detail.discussion_board_channel_id)(sectionInput.discussion_board_channel_id);
  TestValidator.equals("code")(detail.code)(sectionInput.code);
  TestValidator.equals("name")(detail.name)(sectionInput.name);
  TestValidator.equals("description")(detail.description)(sectionInput.description);

  // 5. created_at / updated_at은 ISO8601임을 체크
  TestValidator.equals("created_at is iso8601")(typeof detail.created_at === "string" && !isNaN(Date.parse(detail.created_at)))(true);
  TestValidator.equals("updated_at is iso8601")(typeof detail.updated_at === "string" && !isNaN(Date.parse(detail.updated_at)))(true);

  // 6. deleted_at 소프트딜리트(생성/조회 직후 반드시 null/undefined)
  TestValidator.equals("deleted_at is null or undefined")(
    detail.deleted_at === null || detail.deleted_at === undefined
  )(true);

  // 7. 스키마 외 속성이 응답에 없는지(point: 계약 엄수 / extraneous property 금지)
  const schemaKeys = ["id","discussion_board_channel_id","code","name","description","created_at","updated_at","deleted_at"];
  const detailKeys = Object.keys(detail);
  TestValidator.equals("no extraneous property")(detailKeys.sort())(schemaKeys.sort());
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
