/**
 * Validate error handling for retrieving discussion board section details with an invalid or deleted id.
 *
 * This test confirms that the API correctly returns a not-found error when attempting to fetch section details for:
 * 1. A completely random/non-existent section UUID (should not exist in the DB)
 * 2. An id of a section that was present but is now soft-deleted (deleted_at is set)
 *
 * Because there is no section creation API available, we simulate both cases by using randomly generated UUIDs. The eraseById (soft delete) call may itself produce a not-found error, but this still validates correct error handling. In both steps, the expectation is a not-found error from the API (runtime error, typically HTTP 404).
 *
 * Steps:
 * 1. Attempt to GET section details with a random UUID; confirm error is thrown.
 * 2. Attempt to soft-delete (erase) a random UUID and then fetch it; both actions should error (both unavailable id).
 */
export async function test_api_discussionBoard_systematic_sections_getById_invalid_id_returns_error(
  connection: api.IConnection,
) {
  // 1. Attempt to fetch with a random (likely non-existent) UUID
  const randomId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("not-found for random uuid")(async () => {
    await api.functional.discussionBoard.systematic.sections.getById(connection, {
      id: randomId,
    });
  });

  // 2. Attempt to erase (soft-delete) another random UUID, then fetch it
  const deletedId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("not-found on erase for random id")(async () => {
    await api.functional.discussionBoard.systematic.sections.eraseById(connection, { id: deletedId });
  });
  await TestValidator.error("not-found after erase attempt for random id")(async () => {
    await api.functional.discussionBoard.systematic.sections.getById(connection, { id: deletedId });
  });
}

