import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardChannel";
import type { IDiscussionBoardSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSection";

/**
 * Test successful soft deletion of an active section.
 *
 * This E2E test validates that a section in the discussion board can be soft-deleted (logical deletion, not hard delete).
 * The scenario verifies:
 *   - A channel can be created as a parent entity.
 *   - A section is created, initially present and active (deleted_at: null).
 *   - Soft delete (eraseById) sets deleted_at (ISO8601 string), but retains all other attributes.
 *   - The section record is still available after soft deletion (for audit & reversibility).
 *   - Soft delete is idempotent: repeated deletion remains safe and persists the deleted_at timestamp or updates it.
 *
 * Steps:
 * 1. Create a discussion board channel (parent entity).
 * 2. Create a section under the created channel.
 * 3. Perform a soft delete on the section.
 * 4. Validate deleted_at is now set, but all other fields are unchanged.
 * 5. Optionally, repeat the delete; verify record remains and deleted_at is set/persisted.
 */
export async function test_api_discussionBoard_systematic_sections_test_soft_delete_section_by_id_success(
  connection: api.IConnection,
) {
  // 1. Create a channel as parent for the section
  const channelInput = {
    code: RandomGenerator.alphabets(6),
    name: RandomGenerator.alphabets(10),
    description: RandomGenerator.paragraph()(),
  } satisfies IDiscussionBoardChannel.ICreate;
  const channel = await api.functional.discussionBoard.systematic.channels.post(
    connection,
    { body: channelInput },
  );
  typia.assert(channel);

  // 2. Create a section under the channel
  const sectionInput = {
    discussion_board_channel_id: channel.id,
    code: RandomGenerator.alphabets(8),
    name: RandomGenerator.alphabets(10),
    description: RandomGenerator.paragraph()(),
  } satisfies IDiscussionBoardSection.ICreate;
  const section = await api.functional.discussionBoard.systematic.sections.post(
    connection,
    { body: sectionInput },
  );
  typia.assert(section);
  TestValidator.equals("section linked to channel")(section.discussion_board_channel_id)(channel.id);
  TestValidator.equals("initially, deleted_at is null")(section.deleted_at)(null);

  // 3. Soft delete the section
  const deletedSection = await api.functional.discussionBoard.systematic.sections.eraseById(
    connection,
    { id: section.id },
  );
  typia.assert(deletedSection);

  // 4. Validate: deleted_at is now set; other fields unchanged
  TestValidator.equals("section id remains")(deletedSection.id)(section.id);
  TestValidator.equals("still linked to channel")(deletedSection.discussion_board_channel_id)(channel.id);
  TestValidator.equals("code unchanged")(deletedSection.code)(section.code);
  TestValidator.equals("name unchanged")(deletedSection.name)(section.name);
  TestValidator.equals("description unchanged")(deletedSection.description)(section.description);
  TestValidator.predicate("deleted_at is string & ISO8601")(
    typeof deletedSection.deleted_at === "string" &&
    !!deletedSection.deleted_at &&
    !isNaN(Date.parse(deletedSection.deleted_at))
  );
  TestValidator.notEquals("deleted_at is not null after erase")(deletedSection.deleted_at)(null);

  // 5. Optional: repeat delete to probe idempotency and persistence
  const redeletedSection = await api.functional.discussionBoard.systematic.sections.eraseById(
    connection,
    { id: section.id },
  );
  typia.assert(redeletedSection);
  TestValidator.equals("section id still matches")(redeletedSection.id)(section.id);
  TestValidator.predicate("deleted_at remains valid and is persistent")(
    !!redeletedSection.deleted_at &&
    (!deletedSection.deleted_at ||
      new Date(redeletedSection.deleted_at).getTime() >=
        new Date(deletedSection.deleted_at as string).getTime())
  );
  TestValidator.equals("code still unchanged")(redeletedSection.code)(section.code);
  TestValidator.equals("name still unchanged")(redeletedSection.name)(section.name);
  TestValidator.equals("description still unchanged")(redeletedSection.description)(section.description);
  TestValidator.equals("channel id still matches")(redeletedSection.discussion_board_channel_id)(channel.id);
}

