import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Ensure the API strictly enforces request schema validation during moderation report filtering/listing.
 *
 * This test confirms that only schema-defined fields can be used in filter/search requests to the moderation report endpoint. Any extraneous fields—such as 'created_by', 'updated_by', or arbitrary keys—should cause the API to reject the request with an error, strictly enforcing input validation at the schema level.
 *
 * Test Steps:
 * 1. Send a valid request with only schema-permitted fields and verify a successful paginated response (baseline behavior).
 * 2. Attempt requests including non-schema fields (e.g., 'created_by', 'foo') and confirm that errors are thrown for schema violations.
 * 3. Ensure errors are due to request shape/schema and not downstream business logic.
 */
export async function test_api_discussionBoard_test_list_reports_with_search_fields_not_in_schema(
  connection: api.IConnection,
) {
  // 1. Baseline: Valid request using only schema fields should succeed.
  const validRequest: IDiscussionBoardReport.IRequest = {
    page: 1,
    limit: 3,
  };
  const validResult = await api.functional.discussionBoard.moderation.reports.patch(connection, { body: validRequest });
  typia.assert(validResult);
  TestValidator.predicate("pagination is present")(!!validResult.pagination);
  TestValidator.predicate("data is an array")(Array.isArray(validResult.data));

  // 2. Invalid: Extra non-schema field 'created_by' should fail.\n
  // The 'as any' cast is used intentionally for negative testing: it bypasses TypeScript validation\n  // to allow sending invalid shapes to the runtime for strict API schema enforcement.
  const invalidRequest = { ...validRequest, created_by: "something" } as any;
  await TestValidator.error("API should reject non-schema field 'created_by'")(
    async () => {
      await api.functional.discussionBoard.moderation.reports.patch(connection, { body: invalidRequest });
    }
  );

  // 3. Invalid: Another arbitrary field ('foo')
  const invalidRequest2 = { ...validRequest, foo: 123 } as any;
  await TestValidator.error("API should reject non-schema field 'foo'")(
    async () => {
      await api.functional.discussionBoard.moderation.reports.patch(connection, { body: invalidRequest2 });
    }
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";
import type { IPageIDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardReport";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test that PATCH /discussionBoard/moderation/reports correctly lists reports including soft-deleted ones when requested by filter.
 *
 * 이 테스트는 다음과 같은 실제 moderation 워크플로우에 따라 설계되었습니다:
 *
 * 1. 신고를 생성할 멤버(리포터) 계정을 생성
 * 2. (보조용) 리포트 대상이 될 별도의 멤버를 생성
 * 3. 한 멤버가 새로운 스레드를 생성(이 스레드가 신고 타겟이 됨)
 * 4. reporter가 해당 스레드에 moderation 리포트 생성
 * 5. 해당 리포트를 soft-delete(eraseById)
 * 6. deleted: true 옵션으로 PATCH reports 리스트 조회 → 삭제된 리포트가 반환되는지 확인
 * 7. deleted: false 옵션으로 리스트 조회 → 삭제된 리포트가 미포함되는지 확인
 *
 * 각 단계별로 타입 체크(typia.assert)와 TestValidator 로직 검증을 모두 수행합니다.
 */
export async function test_api_discussionBoard_test_list_reports_including_deleted(
  connection: api.IConnection,
) {
  // 1. 신고하는 멤버(reporter) 계정 생성
  const reporter = await api.functional.discussionBoard.actors.members.post(
    connection,
    {
      body: {
        username: RandomGenerator.alphabets(12),
        email: typia.random<string & tags.Format<"email">>(),
        hashed_password: RandomGenerator.alphaNumeric(32),
        display_name: RandomGenerator.name(),
        is_active: true,
        profile_image_url: null,
      },
    },
  );
  typia.assert(reporter);

  // 2. 리포트 대상 - 별도 멤버 생성(테스트 플로우의 분리성 확보)
  const other_member = await api.functional.discussionBoard.actors.members.post(
    connection,
    {
      body: {
        username: RandomGenerator.alphabets(12),
        email: typia.random<string & tags.Format<"email">>(),
        hashed_password: RandomGenerator.alphaNumeric(32),
        display_name: RandomGenerator.name(),
        is_active: true,
        profile_image_url: null,
      },
    },
  );
  typia.assert(other_member);

  // 3. reporter가 새로운 스레드 생성(리포트 타겟)
  const thread = await api.functional.discussionBoard.articles.threads.post(
    connection,
    {
      body: {
        discussion_board_category_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        title: RandomGenerator.paragraph()(1),
        body: RandomGenerator.content()()(1),
        is_pinned: false,
        is_closed: false,
      },
    },
  );
  typia.assert(thread);

  // 4. reporter가 새로 생성한 스레드에 moderation 리포트 생성
  const report = await api.functional.discussionBoard.moderation.reports.post(
    connection,
    {
      body: {
        reporter_member_id: reporter.id,
        thread_id: thread.id,
        post_id: null,
        comment_id: null,
        reason: "Violation of guidelines (test)",
        status: "pending",
      },
    },
  );
  typia.assert(report);

  // 5. 해당 리포트를 소프트 삭제(eraseById)
  const deleted_report =
    await api.functional.discussionBoard.moderation.reports.eraseById(
      connection,
      {
        id: report.id,
      },
    );
  typia.assert(deleted_report);
  TestValidator.predicate("deleted_at 필드가 존재해야 함")(
    !!deleted_report.deleted_at,
  );

  // 6. deleted: true 옵션으로 신고 리스트 요청 → 삭제 리포트 포함 확인
  const reports_with_deleted =
    await api.functional.discussionBoard.moderation.reports.patch(connection, {
      body: {
        deleted: true,
        page: 1,
        limit: 20,
        reporter_member_id: null,
        moderator_id: null,
        thread_id: null,
        post_id: null,
        comment_id: null,
        reason: null,
        status: null,
        created_at_from: null,
        created_at_to: null,
        sort: null,
        order: null,
      },
    });
  typia.assert(reports_with_deleted);
  const found = reports_with_deleted.data.find((r) => r.id === report.id);
  TestValidator.predicate(
    "deleted=true 필터시 삭제된 리포트가 포함되어야 함",
  )(!!found && !!found.deleted_at);

  // 7. deleted: false 옵션으로 신고 리스트 요청 → 삭제된 리포트 미포함 확인
  const reports_excluding_deleted =
    await api.functional.discussionBoard.moderation.reports.patch(connection, {
      body: {
        deleted: false,
        page: 1,
        limit: 20,
        reporter_member_id: null,
        moderator_id: null,
        thread_id: null,
        post_id: null,
        comment_id: null,
        reason: null,
        status: null,
        created_at_from: null,
        created_at_to: null,
        sort: null,
        order: null,
      },
    });
  typia.assert(reports_excluding_deleted);
  const shouldNotBeFound = reports_excluding_deleted.data.find(
    (r) => r.id === report.id,
  );
  TestValidator.equals(
    "deleted=false 필터시 삭제된 리포트가 미포함되어야 함",
  )(shouldNotBeFound)(undefined);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";

/**
 * 유효한 신고ID로 중재 리포트 상세 조회 (GET by id)
 *
 * - 신규 회원을 생성한 뒤, 신고 대상 스레드를 등록합니다.
 * - 해당 스레드에 대해 moderation(신고) 리포트를 생성합니다.
 * - 등록된 신고 리포트의 id로 상세조회(getById)를 호출하여,
