import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionBoardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardMembers";
import type { IdiscussionBoardModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionBoardModerators";
import type { IPageIdiscussionBoardModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIdiscussionBoardModerators";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate moderator assignments listing with various filters.
 *
 * This test ensures that listing moderator assignments (PATCH /discussionBoard/actors/moderators) with various filtering criteria (by member_id, assigned_at, etc.) works correctly. The test covers:
 *
 * 1. Creating multiple member accounts as the data pool
 * 2. Assigning the moderator role to a subset of those members, storing assignment timestamps
 * 3. Performing searches on moderator assignments with different filters:
 *    - Exact member_id
 *    - assigned_at exact value or outside range
 *    - revoked_at: ensure active moderation only when filter revocation is null
 *    - Pagination (by limiting results per page)
 * 4. Verifying that only appropriate assignments are returned for each filter, that revoked assignments are excluded unless specifically filtered, and that pagination metadata is correct.
 *
 * Business context: This test simulates the real-world administrative workflows of assigning and listing moderators in a discussion board (like a forum) and ensures robust, reliable back-office filtering for member management, audit, and privilege checks.
 */
export async function test_api_discussionBoard_actors_moderators_test_list_moderator_assignments_with_filtering(connection: api.IConnection) {
  // Step 1: Create multiple members
  const members = await Promise.all(ArrayUtil.repeat(5)(async () => {
    const member = await api.functional.discussionBoard.actors.members.post(connection, {
      body: {
        username: RandomGenerator.alphaNumeric(8),
        email: typia.random<string & tags.Format<"email">>(),
        hashed_password: RandomGenerator.alphaNumeric(12),
        display_name: RandomGenerator.name(),
        profile_image_url: null,
        is_active: true,
      },
    });
    typia.assert(member);
    return member;
  }));

  // Step 2: Assign moderator role to a subset of members, record assignment time
  const moderators = await Promise.all(members.slice(0, 3).map(async (member) => {
    const assigned_at = new Date().toISOString();
    const moderator = await api.functional.discussionBoard.actors.moderators.post(connection, {
      body: {
        member_id: member.id,
        assigned_at,
      },
    });
    typia.assert(moderator);
    return moderator;
  }));

  // Step 3-1: List all moderators with no filters, expect 3 active mods
  let result = await api.functional.discussionBoard.actors.moderators.patch(connection, {
    body: {
      page: 1,
      limit: 100,
    },
  });
  typia.assert(result);
  TestValidator.equals("active moderator count")(result.data.length)(3);
  TestValidator.predicate("all currently assigned")(result.data.every((m) => m.revoked_at === null));

  // Step 3-2: Filter by member_id (first moderator), expect only this one
  result = await api.functional.discussionBoard.actors.moderators.patch(connection, {
    body: {
      member_id: moderators[0].member_id,
      page: 1,
      limit: 10,
    },
  });
  typia.assert(result);
  TestValidator.equals("filter by member_id")(result.data.length)(1);
  TestValidator.equals("correct moderator")(result.data[0].member_id)(moderators[0].member_id);

  // Step 3-3: Filter by assigned_at (using second moderator's timestamp)
  result = await api.functional.discussionBoard.actors.moderators.patch(connection, {
    body: {
      assigned_at: moderators[1].assigned_at,
      page: 1,
      limit: 10,
    },
  });
  typia.assert(result);
  TestValidator.equals("filter by assigned_at")(result.data.length)(1);
  TestValidator.equals("correct moderator by assigned_at")(result.data[0].assigned_at)(moderators[1].assigned_at);

  // Step 3-4: Pagination test - limit 2 on first page, expect exactly 2
  result = await api.functional.discussionBoard.actors.moderators.patch(connection, {
    body: {
      page: 1,
      limit: 2,
    },
  });
  typia.assert(result);
  TestValidator.equals("limit 2, first page")(result.data.length)(2);
  TestValidator.equals("pagination.current")(result.pagination.current)(1);
  TestValidator.equals("pagination.limit")(result.pagination.limit)(2);
  TestValidator.predicate("pagination.pages >= 2")(result.pagination.pages >= 2);

  // Step 3-5: revoked_at - filter to active only
  result = await api.functional.discussionBoard.actors.moderators.patch(connection, {
    body: {
      revoked_at: null,
      page: 1,
      limit: 5,
    },
  });
  typia.assert(result);
  TestValidator.equals("active only with revoked_at null")(result.data.length)(3);
  TestValidator.predicate("all item revoked_at null")(result.data.every((m) => m.revoked_at === null));
}

